export const FILMATY_WEBAPP_HTML = "<!DOCTYPE html>\r\n<html lang=\"ar\" dir=\"rtl\">\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <meta name=\"theme-color\" content=\"#0b0f19\">\r\n  <link rel=\"manifest\" href=\"manifest.json\">\r\n  <link rel=\"apple-touch-icon\" href=\"icons/icon-192.png\">\r\n  <title>فيلماتي | سينما وأفلام ومسلسلات بجودة فائقة</title>\r\n  <!-- Telegram WebApp JS -->\r\n  <script src=\"https://telegram.org/js/telegram-web-app.js\"></script>\r\n  <!-- Tailwind CSS CDN -->\r\n  <script src=\"https://cdn.tailwindcss.com\"></script>\r\n  <script>\r\n    tailwind.config = {\r\n      theme: {\r\n        extend: {\r\n          colors: {\r\n            brand: {\r\n              red: '#e50914',\r\n              gold: '#f59e0b',\r\n              dark: '#141414',\r\n              card: '#181818',\r\n              border: '#2e2e2e'\r\n            }\r\n          }\r\n        }\r\n      }\r\n    }\r\n  </script>\r\n  <style>\r\n    @import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;800;900&display=swap');\r\n    html { color-scheme: dark; }\r\n    * { font-family: 'Cairo', system-ui, -apple-system, sans-serif; }\r\n    body { background-color: #141414; color: #ffffff; }\r\n    *:not(.scrollbar-hide) { scrollbar-width: thin; scrollbar-color: #525252 #181818; }\r\n    *:not(.scrollbar-hide)::-webkit-scrollbar { width: 8px; height: 8px; }\r\n    *:not(.scrollbar-hide)::-webkit-scrollbar-track { background: #181818; }\r\n    *:not(.scrollbar-hide)::-webkit-scrollbar-thumb { background: #454545; border-radius: 9999px; }\r\n    *:not(.scrollbar-hide)::-webkit-scrollbar-thumb:hover { background: #737373; }\r\n    .glass { background: rgba(20, 20, 20, 0.9); backdrop-filter: blur(10px); border-bottom: 1px solid rgba(255, 255, 255, 0.08); }\r\n    .hero-scrim { background: linear-gradient(to top, #141414 4%, rgba(20, 20, 20, 0.78) 45%, rgba(20, 20, 20, 0.25) 100%), linear-gradient(to left, rgba(20, 20, 20, 0.88) 0%, rgba(20, 20, 20, 0.45) 55%, rgba(20, 20, 20, 0.1) 100%); }\r\n    .modal-backdrop-scrim { background: linear-gradient(to top, #181818 6%, rgba(24, 24, 24, 0.65) 55%, rgba(24, 24, 24, 0.2) 100%); }\r\n    .line-clamp-2 { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }\r\n    .line-clamp-3 { display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }\r\n    .scrollbar-hide::-webkit-scrollbar { display: none; }\r\n    .scrollbar-hide { -ms-overflow-style: none; scrollbar-width: none; }\r\n    button:not(:disabled), a[href], select, [role=\"button\"] { cursor: pointer; }\r\n    button:disabled { cursor: not-allowed; opacity: 0.6; }\r\n    :focus-visible { outline: 2px solid #f59e0b; outline-offset: 2px; }\r\n    #modalCard.theater-mode { max-width: 68rem; }\r\n    @media (prefers-reduced-motion: reduce) {\r\n      *, *::before, *::after { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; scroll-behavior: auto !important; }\r\n    }\r\n  </style>\r\n</head>\r\n<body class=\"min-h-screen flex flex-col pb-12\">\r\n\r\n  <!-- Header -->\r\n  <header class=\"sticky top-0 z-40 glass px-4 sm:px-6 py-2.5\">\r\n    <div class=\"max-w-7xl mx-auto w-full flex items-center justify-between gap-3\">\r\n      <div class=\"flex items-center gap-3 min-w-0\">\r\n        <button id=\"menuBtn\" type=\"button\" aria-label=\"القائمة\" class=\"min-w-[44px] min-h-[44px] rounded-md bg-[#232323] border border-[#737373] text-white text-lg font-bold flex items-center justify-center hover:border-white transition\">☰</button>\r\n        <h1 id=\"brandHomeBtn\" role=\"button\" tabindex=\"0\" class=\"text-2xl sm:text-3xl font-black tracking-tight text-[#e50914] select-none shrink-0\">فيلماتي</h1>\r\n        <nav aria-label=\"التصفح السريع\" class=\"hidden md:flex items-center gap-1 mr-3 text-xs\">\r\n          <button type=\"button\" data-nav-filter=\"trending\" class=\"nav-filter-link px-3 py-2 rounded-md text-white font-black hover:text-white transition\">الرئيسية</button>\r\n          <button type=\"button\" data-nav-filter=\"movie\" class=\"nav-filter-link px-3 py-2 rounded-md text-neutral-300 font-semibold hover:text-white transition\">أفلام</button>\r\n          <button type=\"button\" data-nav-filter=\"tv\" class=\"nav-filter-link px-3 py-2 rounded-md text-neutral-300 font-semibold hover:text-white transition\">مسلسلات</button>\r\n          <button type=\"button\" data-nav-filter=\"netflix\" class=\"nav-filter-link px-3 py-2 rounded-md text-neutral-300 font-semibold hover:text-white transition\">نتفليكس</button>\r\n          <button type=\"button\" data-nav-filter=\"marvel\" class=\"nav-filter-link px-3 py-2 rounded-md text-neutral-300 font-semibold hover:text-white transition\">مارفل</button>\r\n        </nav>\r\n      </div>\r\n      <div class=\"flex items-center gap-2 shrink-0\">\r\n        <a href=\"Tv/\" class=\"min-h-[44px] flex items-center gap-1.5 px-3 sm:px-3.5 rounded-md bg-[#232323] text-white border border-[#737373] hover:border-white text-xs font-bold transition\">\r\n          <span>📺 وضع التلفزيون</span>\r\n        </a>\r\n        <a href=\"https://t.me/filmatibot\" target=\"_blank\" rel=\"noopener\" class=\"min-h-[44px] flex items-center gap-1.5 px-3 sm:px-3.5 rounded-md bg-[#232323] text-neutral-200 border border-[#737373] hover:border-white text-xs font-bold transition\">\r\n          <span>البوت</span>\r\n        </a>\r\n      </div>\r\n    </div>\r\n  </header>\r\n\r\n  <!-- Side drawer (hamburger menu): categories by language, top-rated, collections -->\r\n  <div id=\"drawerOverlay\" class=\"fixed inset-0 z-[55] bg-black/75 hidden\"></div>\r\n  <aside id=\"sideDrawer\" class=\"fixed inset-y-0 right-0 z-[60] w-72 max-w-[85vw] bg-[#181818] border-l border-neutral-800 shadow-2xl overflow-y-auto transition-transform duration-300 translate-x-full\" aria-label=\"قائمة التصنيفات\">\r\n    <div class=\"sticky top-0 z-10 flex items-center justify-between px-4 py-3 bg-[#181818] border-b border-neutral-800\">\r\n      <span class=\"text-base font-extrabold text-white\">☰ القائمة</span>\r\n      <button id=\"drawerClose\" type=\"button\" aria-label=\"إغلاق القائمة\" class=\"min-w-[44px] min-h-[44px] rounded-full bg-[#232323] border border-[#737373] text-white flex items-center justify-center hover:border-white transition\">✕</button>\r\n    </div>\r\n    <nav class=\"p-3 space-y-1 text-sm font-bold\">\r\n      <div>\r\n        <button class=\"drawer-group-btn w-full flex items-center justify-between px-3 py-2.5 rounded-xl bg-slate-800/70 text-white hover:bg-slate-800 transition\" data-group=\"movies\">\r\n          <span>🎬 أفلام</span><span class=\"drawer-arrow text-slate-400\">▾</span>\r\n        </button>\r\n        <div id=\"drawer-movies\" class=\"drawer-sub hidden pr-3 pt-1 space-y-1\">\r\n          <button class=\"drawer-lang w-full text-right px-3 py-2 rounded-xl text-slate-300 hover:bg-slate-800 hover:text-white transition\" data-type=\"movie\" data-lang=\"ar\">عربي</button>\r\n          <button class=\"drawer-lang w-full text-right px-3 py-2 rounded-xl text-slate-300 hover:bg-slate-800 hover:text-white transition\" data-type=\"movie\" data-lang=\"en\" data-origin=\"US\">🇺🇸 إنجليزي (أمريكي)</button>\r\n          <div>\r\n            <button class=\"drawer-group-btn w-full flex items-center justify-between px-3 py-2 rounded-xl text-slate-300 hover:bg-slate-800 hover:text-white transition\" data-group=\"movies-other\">\r\n              <span>🌍 لغات أخرى</span><span class=\"drawer-arrow text-slate-400\">▾</span>\r\n            </button>\r\n            <div id=\"drawer-movies-other\" class=\"drawer-sub hidden pr-3 pt-1 space-y-1\">\r\n              <button class=\"drawer-lang w-full text-right px-3 py-2 rounded-xl text-slate-300 hover:bg-slate-800 hover:text-white transition\" data-type=\"movie\" data-lang=\"hi\">هندي</button>\r\n              <button class=\"drawer-lang w-full text-right px-3 py-2 rounded-xl text-slate-300 hover:bg-slate-800 hover:text-white transition\" data-type=\"movie\" data-lang=\"tr\">تركي</button>\r\n              <button class=\"drawer-lang w-full text-right px-3 py-2 rounded-xl text-slate-300 hover:bg-slate-800 hover:text-white transition\" data-type=\"movie\" data-lang=\"ko\">كوري</button>\r\n              <button class=\"drawer-lang w-full text-right px-3 py-2 rounded-xl text-slate-300 hover:bg-slate-800 hover:text-white transition\" data-type=\"movie\" data-lang=\"es\">إسباني</button>\r\n              <button class=\"drawer-lang w-full text-right px-3 py-2 rounded-xl text-slate-300 hover:bg-slate-800 hover:text-white transition\" data-type=\"movie\" data-lang=\"fr\">فرنسي</button>\r\n              <button class=\"drawer-lang w-full text-right px-3 py-2 rounded-xl text-slate-300 hover:bg-slate-800 hover:text-white transition\" data-type=\"movie\" data-lang=\"ja\">ياباني</button>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n      <div>\r\n        <button class=\"drawer-group-btn w-full flex items-center justify-between px-3 py-2.5 rounded-xl bg-slate-800/70 text-white hover:bg-slate-800 transition\" data-group=\"tv\">\r\n          <span>📺 مسلسلات</span><span class=\"drawer-arrow text-slate-400\">▾</span>\r\n        </button>\r\n        <div id=\"drawer-tv\" class=\"drawer-sub hidden pr-3 pt-1 space-y-1\">\r\n          <button class=\"drawer-lang w-full text-right px-3 py-2 rounded-xl text-slate-300 hover:bg-slate-800 hover:text-white transition\" data-type=\"tv\" data-lang=\"ar\">عربي</button>\r\n          <button class=\"drawer-lang w-full text-right px-3 py-2 rounded-xl text-slate-300 hover:bg-slate-800 hover:text-white transition\" data-type=\"tv\" data-lang=\"en\" data-origin=\"US\">🇺🇸 إنجليزي (أمريكي)</button>\r\n          <div>\r\n            <button class=\"drawer-group-btn w-full flex items-center justify-between px-3 py-2 rounded-xl text-slate-300 hover:bg-slate-800 hover:text-white transition\" data-group=\"tv-other\">\r\n              <span>🌍 لغات أخرى</span><span class=\"drawer-arrow text-slate-400\">▾</span>\r\n            </button>\r\n            <div id=\"drawer-tv-other\" class=\"drawer-sub hidden pr-3 pt-1 space-y-1\">\r\n              <button class=\"drawer-lang w-full text-right px-3 py-2 rounded-xl text-slate-300 hover:bg-slate-800 hover:text-white transition\" data-type=\"tv\" data-lang=\"hi\">هندي</button>\r\n              <button class=\"drawer-lang w-full text-right px-3 py-2 rounded-xl text-slate-300 hover:bg-slate-800 hover:text-white transition\" data-type=\"tv\" data-lang=\"tr\">تركي</button>\r\n              <button class=\"drawer-lang w-full text-right px-3 py-2 rounded-xl text-slate-300 hover:bg-slate-800 hover:text-white transition\" data-type=\"tv\" data-lang=\"ko\">كوري</button>\r\n              <button class=\"drawer-lang w-full text-right px-3 py-2 rounded-xl text-slate-300 hover:bg-slate-800 hover:text-white transition\" data-type=\"tv\" data-lang=\"es\">إسباني</button>\r\n              <button class=\"drawer-lang w-full text-right px-3 py-2 rounded-xl text-slate-300 hover:bg-slate-800 hover:text-white transition\" data-type=\"tv\" data-lang=\"fr\">فرنسي</button>\r\n              <button class=\"drawer-lang w-full text-right px-3 py-2 rounded-xl text-slate-300 hover:bg-slate-800 hover:text-white transition\" data-type=\"tv\" data-lang=\"ja\">ياباني</button>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n      <button id=\"drawerTopRated\" class=\"w-full text-right px-3 py-2.5 rounded-xl text-white hover:bg-slate-800 transition\">⭐ الأعلى تقييمًا</button>\r\n      <button id=\"drawerMarvel\" class=\"w-full text-right px-3 py-2.5 rounded-xl text-white hover:bg-slate-800 transition\">🦸‍♂️ مارفل</button>\r\n      <button id=\"drawerNetflix\" class=\"w-full text-right px-3 py-2.5 rounded-xl text-white hover:bg-slate-800 transition\">🔴 نتفليكس</button>\r\n    </nav>\r\n  </aside>\r\n\r\n  <!-- Search & Category Filters -->\r\n  <section class=\"px-4 sm:px-6 pt-4 pb-2 max-w-7xl mx-auto w-full\">\r\n    <div class=\"relative\">\r\n      <label for=\"searchInput\" class=\"sr-only\">ابحث عن فيلم أو مسلسل</label>\r\n      <input\r\n        id=\"searchInput\"\r\n        type=\"text\"\r\n        placeholder=\"ابحث عن فيلم، مسلسل، Marvel، Netflix...\"\r\n        class=\"w-full bg-[#1f1f1f] text-white placeholder-neutral-400 rounded-md min-h-[46px] py-2.5 pr-11 pl-12 border border-[#737373] focus:border-white focus:outline-none transition text-sm\"\r\n      />\r\n      <span class=\"absolute right-3.5 top-3 text-neutral-400 text-base pointer-events-none\" aria-hidden=\"true\">🔍</span>\r\n      <button id=\"clearSearch\" type=\"button\" aria-label=\"مسح البحث\" class=\"hidden absolute left-2 top-1.5 text-neutral-300 hover:text-white text-sm bg-[#2a2a2a] rounded-full w-8 h-8 flex items-center justify-center\">✕</button>\r\n      <!-- Search suggestions dropdown (stage E) -->\r\n      <div id=\"searchSuggest\" class=\"hidden absolute right-0 left-0 top-full mt-2 bg-[#181818] border border-neutral-700 rounded-md shadow-2xl z-40 overflow-hidden\"></div>\r\n    </div>\r\n\r\n    <!-- Quick Filters -->\r\n    <div class=\"flex gap-2 overflow-x-auto scrollbar-hide py-3 mt-1 text-xs font-bold\">\r\n      <button type=\"button\" class=\"filter-btn active min-h-[44px] whitespace-nowrap px-4 py-2 rounded-md bg-[#e50914] border border-[#e50914] text-white transition\" data-filter=\"trending\">🔥 الأكثر رواجاً</button>\r\n      <button type=\"button\" class=\"filter-btn min-h-[44px] whitespace-nowrap px-4 py-2 rounded-md bg-[#232323] text-neutral-200 border border-[#737373] hover:border-white transition\" data-filter=\"movie\">🎬 أفلام</button>\r\n      <button type=\"button\" class=\"filter-btn min-h-[44px] whitespace-nowrap px-4 py-2 rounded-md bg-[#232323] text-neutral-200 border border-[#737373] hover:border-white transition\" data-filter=\"tv\">📺 مسلسلات</button>\r\n      <button type=\"button\" class=\"filter-btn min-h-[44px] whitespace-nowrap px-4 py-2 rounded-md bg-[#232323] text-neutral-200 border border-[#737373] hover:border-white transition\" data-filter=\"marvel\">🦸‍♂️ مارفل</button>\r\n      <button type=\"button\" class=\"filter-btn min-h-[44px] whitespace-nowrap px-4 py-2 rounded-md bg-[#232323] text-neutral-200 border border-[#737373] hover:border-white transition\" data-filter=\"netflix\">🔴 نتفليكس</button>\r\n    </div>\r\n  </section>\r\n\r\n  <!-- Main Content Grid -->\r\n  <main class=\"flex-1 max-w-7xl mx-auto w-full px-4 sm:px-6\">\r\n    <!-- Netflix Featured Hero Billboard -->\r\n    <section id=\"heroBanner\" class=\"hidden relative w-full aspect-[16/11] sm:aspect-[21/9] max-h-[460px] rounded-xl overflow-hidden bg-[#181818] border border-neutral-800 mb-8\">\r\n      <img id=\"heroImg\" src=\"\" alt=\"\" fetchpriority=\"high\" class=\"w-full h-full object-cover object-center\" />\r\n      <div class=\"hero-scrim absolute inset-0\"></div>\r\n      <div class=\"absolute inset-x-0 bottom-0 p-5 sm:p-8 md:p-10 max-w-2xl space-y-2.5\">\r\n        <div class=\"flex flex-wrap items-center gap-2.5 text-xs font-bold text-neutral-200\">\r\n          <span class=\"px-2 py-0.5 rounded bg-[#e50914] text-white font-extrabold\">مختارات فيلماتي</span>\r\n          <span id=\"heroKind\"></span>\r\n          <span id=\"heroYear\"></span>\r\n          <span id=\"heroRating\" class=\"text-amber-400 font-extrabold\"></span>\r\n        </div>\r\n        <h2 id=\"heroTitle\" class=\"font-black text-white leading-tight\" style=\"font-size: clamp(1.5rem, 3.8vw, 2.75rem);\"></h2>\r\n        <p id=\"heroOverview\" class=\"text-neutral-200 text-xs sm:text-sm line-clamp-2 leading-relaxed max-w-xl\"></p>\r\n        <div class=\"flex flex-wrap items-center gap-3 pt-1\">\r\n          <button id=\"heroPlayBtn\" type=\"button\" class=\"min-h-[44px] px-6 py-2.5 rounded-md bg-white hover:bg-neutral-200 text-black font-black text-sm flex items-center gap-2 transition\">▶ تشغيل الآن</button>\r\n          <button id=\"heroInfoBtn\" type=\"button\" class=\"min-h-[44px] px-5 py-2.5 rounded-md bg-neutral-800/90 hover:bg-neutral-700 text-white border border-[#737373] font-bold text-sm flex items-center gap-2 transition\">تفاصيل العمل</button>\r\n        </div>\r\n      </div>\r\n    </section>\r\n\r\n    <!-- Section Title -->\r\n    <div id=\"gridHeader\" class=\"flex items-center justify-between mb-3\">\r\n      <h2 id=\"sectionTitle\" class=\"text-base sm:text-lg font-extrabold text-white flex items-center gap-2\">\r\n        <span>🔥</span> <span>الأعمال الأكثر رواجاً اليوم</span>\r\n      </h2>\r\n      <span id=\"itemsCount\" class=\"text-xs text-[#a3a3a3] font-semibold\"></span>\r\n    </div>\r\n\r\n    <!-- Media Cards Grid -->\r\n    <div id=\"mediaGrid\" class=\"grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-3 sm:gap-4\">\r\n      <!-- Loading placeholders -->\r\n      <div class=\"animate-pulse bg-[#181818] rounded-md aspect-[2/3] border border-neutral-800\"></div>\r\n      <div class=\"animate-pulse bg-[#181818] rounded-md aspect-[2/3] border border-neutral-800\"></div>\r\n      <div class=\"animate-pulse bg-[#181818] rounded-md aspect-[2/3] border border-neutral-800\"></div>\r\n      <div class=\"animate-pulse bg-[#181818] rounded-md aspect-[2/3] border border-neutral-800\"></div>\r\n      <div class=\"animate-pulse bg-[#181818] rounded-md aspect-[2/3] border border-neutral-800\"></div>\r\n      <div class=\"animate-pulse bg-[#181818] rounded-md aspect-[2/3] border border-neutral-800 hidden lg:block\"></div>\r\n    </div>\r\n\r\n    <!-- Home Sections (most-watched first, then top-rated; year filter chips) -->\r\n    <div id=\"homeSections\" class=\"hidden space-y-9\"></div>\r\n  </main>\r\n\r\n  <!-- Media Details & Player Modal -->\r\n  <div id=\"mediaModal\" class=\"fixed inset-0 z-50 bg-black/85 hidden flex items-end sm:items-center justify-center p-0 sm:p-4 transition-opacity\">\r\n    <div id=\"modalCard\" class=\"bg-[#181818] border border-neutral-800 rounded-t-2xl sm:rounded-xl max-w-3xl w-full max-h-[92dvh] flex flex-col overflow-hidden shadow-2xl relative\">\r\n      <!-- Close button -->\r\n      <button id=\"closeModal\" type=\"button\" aria-label=\"إغلاق\" class=\"absolute top-3 left-3 z-20 w-11 h-11 rounded-full bg-[#181818]/90 border border-[#737373] text-white flex items-center justify-center hover:border-white hover:bg-[#e50914] transition\">✕</button>\r\n\r\n      <!-- Modal Backdrop Banner (hidden once player opens) -->\r\n      <div id=\"modalBackdropWrap\" class=\"hidden relative aspect-video max-h-64 sm:max-h-80 w-full bg-neutral-900 overflow-hidden shrink-0\">\r\n        <img id=\"modalBackdropImg\" src=\"\" alt=\"\" class=\"w-full h-full object-cover\" />\r\n        <div class=\"modal-backdrop-scrim absolute inset-0\"></div>\r\n      </div>\r\n\r\n      <!-- Video Player Frame Area -->\r\n      <div id=\"playerContainer\" class=\"hidden relative aspect-video w-full bg-black select-none shrink-0\">\r\n        <iframe id=\"videoIframe\" class=\"w-full h-full\" src=\"\" allowfullscreen frameborder=\"0\" referrerpolicy=\"origin\" allow=\"fullscreen; autoplay; encrypted-media\"></iframe>\r\n        <video id=\"videoNative\" class=\"hidden w-full h-full bg-black\" controls playsinline preload=\"metadata\"></video>\r\n        <div id=\"iframeSpinner\" class=\"hidden absolute inset-0 flex flex-col items-center justify-center gap-2 bg-black/80 text-white text-sm font-bold pointer-events-none\">\r\n          <span class=\"w-8 h-8 border-2 border-red-500 border-t-transparent rounded-full animate-spin\" aria-hidden=\"true\"></span>\r\n          <span>⏳ جاري تحميل المشغّل...</span>\r\n        </div>\r\n        <div id=\"seekIndicator\" class=\"hidden absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 px-4 py-2 rounded-xl bg-black/85 text-white text-sm font-black border border-white/20 pointer-events-none\"></div>\r\n        <div id=\"playerStatus\" class=\"hidden absolute inset-0 flex items-center justify-center bg-black/75 text-white text-sm font-bold px-4 text-center\"></div>\r\n      </div>\r\n\r\n      <!-- Player Controls Bar -->\r\n      <div id=\"playerToolbar\" class=\"hidden flex-wrap items-center justify-between gap-2 px-4 py-2 bg-[#141414] border-b border-neutral-800 text-xs font-bold shrink-0\">\r\n        <div id=\"nativeToolbarGroup\" class=\"flex flex-wrap items-center gap-2\">\r\n          <button id=\"btnSeekBack\" type=\"button\" aria-label=\"ترجيع 10 ثواني\" class=\"min-h-[44px] px-3 py-1.5 rounded-md bg-[#232323] text-neutral-200 border border-[#737373] hover:border-white transition\">-10 ث ⏪</button>\r\n          <button id=\"btnSeekFwd\" type=\"button\" aria-label=\"تقديم 10 ثواني\" class=\"min-h-[44px] px-3 py-1.5 rounded-md bg-[#232323] text-neutral-200 border border-[#737373] hover:border-white transition\">⏩ +10 ث</button>\r\n          <div class=\"flex items-center gap-1.5\">\r\n            <label for=\"playerSpeedSelect\" class=\"text-neutral-300\">السرعة:</label>\r\n            <select id=\"playerSpeedSelect\" class=\"min-h-[44px] bg-[#232323] text-white rounded-md px-2.5 py-1.5 border border-[#737373]\">\r\n              <option value=\"0.5\">0.5x</option>\r\n              <option value=\"0.75\">0.75x</option>\r\n              <option value=\"1\" selected>1x</option>\r\n              <option value=\"1.25\">1.25x</option>\r\n              <option value=\"1.5\">1.5x</option>\r\n              <option value=\"2\">2x</option>\r\n            </select>\r\n          </div>\r\n          <button id=\"btnPip\" type=\"button\" aria-label=\"صورة داخل صورة\" class=\"min-h-[44px] px-3 py-1.5 rounded-md bg-[#232323] text-neutral-200 border border-[#737373] hover:border-white transition\">صورة داخل صورة</button>\r\n        </div>\r\n        <div class=\"flex items-center gap-2\">\r\n          <button id=\"btnTheater\" type=\"button\" aria-label=\"وضع المسرح\" aria-pressed=\"false\" class=\"hidden sm:inline-flex items-center min-h-[44px] px-3 py-1.5 rounded-md bg-[#232323] text-neutral-200 border border-[#737373] hover:border-amber-500 transition\">وضع المسرح</button>\r\n          <button id=\"btnFullscreen\" type=\"button\" aria-label=\"ملء الشاشة\" class=\"min-h-[44px] px-3 py-1.5 rounded-md bg-[#e50914] text-white hover:bg-red-700 transition\">⛶ ملء الشاشة</button>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Modal Content Body -->\r\n      <div class=\"p-4 sm:p-6 overflow-y-auto space-y-5\">\r\n        <!-- Auto-next episode countdown (series only, native player) -->\r\n        <div id=\"autoNextBar\" class=\"hidden items-center justify-between gap-2 rounded-md bg-red-600/20 border border-red-500/40 px-3 py-2\">\r\n          <span id=\"autoNextText\" class=\"text-xs font-bold text-white\">الحلقة التالية خلال 5 ثواني…</span>\r\n          <span class=\"flex gap-2 shrink-0\">\r\n            <button id=\"btnAutoNextNow\" type=\"button\" class=\"min-h-[44px] px-3.5 py-1.5 rounded-md bg-[#e50914] text-white text-xs font-bold\">تشغيل الآن</button>\r\n            <button id=\"btnAutoNextCancel\" type=\"button\" class=\"min-h-[44px] px-3.5 py-1.5 rounded-md bg-[#232323] text-neutral-200 text-xs font-bold border border-[#737373]\">إلغاء</button>\r\n          </span>\r\n        </div>\r\n        <div class=\"flex gap-4 items-start\">\r\n          <img id=\"modalPoster\" src=\"\" alt=\"Poster\" class=\"hidden sm:block w-20 h-28 object-cover rounded-md shadow-md border border-neutral-700 shrink-0 bg-neutral-900\" />\r\n          <div class=\"flex-1 min-w-0\">\r\n            <h3 id=\"modalTitle\" class=\"text-xl sm:text-2xl font-black text-white leading-tight\"></h3>\r\n            <div class=\"flex flex-wrap items-center gap-2.5 mt-2 text-xs\">\r\n              <span id=\"modalRating\" class=\"px-2 py-0.5 rounded bg-emerald-600/20 text-emerald-400 font-bold border border-emerald-500/30\">⭐ 8.5</span>\r\n              <span id=\"modalYear\" class=\"text-[#a3a3a3] font-semibold\">2026</span>\r\n              <span id=\"modalKind\" class=\"px-2 py-0.5 rounded bg-[#232323] text-neutral-200 border border-neutral-700 font-semibold\">فيلم</span>\r\n            </div>\r\n            <p id=\"modalStory\" class=\"text-[#e5e5e5] text-xs sm:text-sm mt-2.5 line-clamp-3 leading-relaxed\"></p>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- Series Seasons & Episodes Picker (Visible if TV show) -->\r\n        <div id=\"seriesControls\" class=\"hidden space-y-3 pt-3 border-t border-neutral-800\">\r\n          <div class=\"flex items-center justify-between gap-3\">\r\n            <label for=\"seasonSelect\" class=\"text-xs font-bold text-neutral-300\">الموسم:</label>\r\n            <select id=\"seasonSelect\" class=\"min-h-[44px] bg-[#232323] text-white text-xs font-bold rounded-md px-3 py-1.5 border border-[#737373] focus:outline-none\"></select>\r\n          </div>\r\n          <div>\r\n            <label class=\"text-xs font-bold text-neutral-300 block mb-2\">اختر الحلقة:</label>\r\n            <div id=\"episodesGrid\" class=\"grid grid-cols-4 sm:grid-cols-6 gap-2 max-h-44 overflow-y-auto pr-1\"></div>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- Server & Quality Picker -->\r\n        <div id=\"serverControls\" class=\"hidden space-y-3 pt-3 border-t border-neutral-800\">\r\n          <div>\r\n            <label class=\"text-xs font-bold text-neutral-300 block mb-1.5\">السيرفر:</label>\r\n            <div id=\"serversRow\" class=\"flex flex-wrap gap-2\"></div>\r\n          </div>\r\n          <div id=\"qualityWrap\">\r\n            <label class=\"text-xs font-bold text-neutral-300 block mb-1.5\">الجودة:</label>\r\n            <div id=\"qualitiesRow\" class=\"flex flex-wrap gap-2\"></div>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- Action Buttons -->\r\n        <div class=\"pt-3 border-t border-neutral-800 space-y-3\">\r\n          <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-2.5\">\r\n            <button id=\"btnPlayInApp\" type=\"button\" class=\"min-h-[46px] w-full py-2.5 px-5 rounded-md bg-white hover:bg-neutral-200 text-black font-black text-sm flex items-center justify-center gap-2 transition\">\r\n              <span>▶</span> <span id=\"btnPlayInAppLabel\">مشاهدة فورية</span>\r\n            </button>\r\n            <button id=\"btnDirectDownload\" type=\"button\" aria-disabled=\"false\" class=\"min-h-[46px] w-full py-2.5 px-5 rounded-md bg-[#262626] hover:bg-[#333333] text-white border border-[#737373] font-bold text-sm flex items-center justify-center gap-2 transition\">\r\n              <span id=\"btnDirectDownloadIcon\">⬇</span> <span id=\"btnDirectDownloadLabel\">تحميل مباشر (.mp4)</span>\r\n            </button>\r\n          </div>\r\n          <!-- Download quality picker (shown when more than one quality exists) -->\r\n          <div id=\"downloadPicker\" class=\"hidden space-y-2 pt-1\">\r\n            <label class=\"text-xs font-bold text-neutral-300 block\">اختر جودة التحميل:</label>\r\n            <div id=\"downloadQualitiesRow\" class=\"flex flex-wrap gap-2\"></div>\r\n          </div>\r\n          <!-- Whole-season download (series only) -->\r\n          <button id=\"btnDownloadSeason\" type=\"button\" class=\"hidden min-h-[44px] w-full py-2.5 px-4 rounded-md bg-[#232323] text-emerald-300 border border-[#737373] font-bold text-xs flex items-center justify-center gap-2 hover:border-white transition\">⬇️ تحميل الموسم كامل</button>\r\n          <div id=\"seasonDownloadPicker\" class=\"hidden space-y-2 pt-1\">\r\n            <label class=\"text-xs font-bold text-neutral-300 block\">اختر جودة تحميل الموسم:</label>\r\n            <div id=\"seasonDownloadQualitiesRow\" class=\"flex flex-wrap gap-2\"></div>\r\n          </div>\r\n          <div id=\"seasonDownloadProgress\" class=\"hidden space-y-1 pt-1 max-h-32 overflow-y-auto pr-1\">\r\n            <label class=\"text-xs font-bold text-neutral-300 block\">تقدّم تحميل الموسم:</label>\r\n            <div id=\"seasonDownloadList\" class=\"space-y-1\"></div>\r\n          </div>\r\n          <!-- Restart from the beginning (shown only when a saved position exists) -->\r\n          <button id=\"btnRestartPlay\" type=\"button\" class=\"hidden min-h-[44px] w-full py-2 rounded-md bg-[#232323] text-neutral-200 border border-[#737373] font-bold text-xs hover:border-white transition\">↺ تشغيل من الأول</button>\r\n          <!-- Secondary actions strip -->\r\n          <div class=\"flex flex-wrap gap-2\">\r\n            <button id=\"btnMyList\" type=\"button\" class=\"flex-1 min-w-[130px] min-h-[44px] px-3 py-2 rounded-md bg-[#232323] text-neutral-200 border border-[#737373] font-bold text-xs flex items-center justify-center gap-1.5 hover:border-white transition\">🤍 أضف لقائمتي</button>\r\n            <button id=\"btnShareMedia\" type=\"button\" class=\"flex-1 min-w-[130px] min-h-[44px] px-3 py-2 rounded-md bg-[#232323] text-neutral-200 border border-[#737373] font-bold text-xs flex items-center justify-center gap-1.5 hover:border-white transition\">🔗 مشاركة</button>\r\n            <button id=\"btnTrailer\" type=\"button\" class=\"hidden flex-1 min-w-[130px] min-h-[44px] px-3 py-2 rounded-md bg-[#232323] text-neutral-200 border border-[#737373] font-bold text-xs flex items-center justify-center gap-1.5 hover:border-white transition\">🎬 مشاهدة التريلر</button>\r\n            <button id=\"btnOpenInBot\" type=\"button\" class=\"flex-1 min-w-[130px] min-h-[44px] px-3 py-2 rounded-md bg-[#232323] text-neutral-200 border border-[#737373] font-bold text-xs flex items-center justify-center gap-1.5 hover:border-white transition\">🚀 إرسال للتليجرام</button>\r\n            <button id=\"btnReport\" type=\"button\" class=\"flex-1 min-w-[130px] min-h-[44px] px-3 py-2 rounded-md bg-[#232323] text-neutral-200 border border-[#737373] font-bold text-xs flex items-center justify-center gap-1.5 hover:border-amber-500 transition\">⚠️ بلّغ عن مشكلة</button>\r\n          </div>\r\n          <div id=\"reportPicker\" class=\"hidden space-y-2 pt-1\">\r\n            <label class=\"text-xs font-bold text-neutral-300 block\">إيه المشكلة؟</label>\r\n            <div class=\"flex flex-wrap gap-2\">\r\n              <button type=\"button\" class=\"report-problem-btn min-h-[44px] px-3 py-1.5 rounded-md text-xs font-bold border bg-[#232323] border-[#737373] text-neutral-200 hover:border-white transition\" data-problem=\"المشغّل مش شغال\">المشغّل مش شغال</button>\r\n              <button type=\"button\" class=\"report-problem-btn min-h-[44px] px-3 py-1.5 rounded-md text-xs font-bold border bg-[#232323] border-[#737373] text-neutral-200 hover:border-white transition\" data-problem=\"الفيديو بيقطّع أو الجودة ضعيفة\">الفيديو بيقطّع</button>\r\n              <button type=\"button\" class=\"report-problem-btn min-h-[44px] px-3 py-1.5 rounded-md text-xs font-bold border bg-[#232323] border-[#737373] text-neutral-200 hover:border-white transition\" data-problem=\"الصوت أو الترجمة فيها مشكلة\">الصوت / الترجمة</button>\r\n              <button type=\"button\" class=\"report-problem-btn min-h-[44px] px-3 py-1.5 rounded-md text-xs font-bold border bg-[#232323] border-[#737373] text-neutral-200 hover:border-white transition\" data-problem=\"مشكلة تانية\">مشكلة تانية</button>\r\n            </div>\r\n            <p class=\"text-[11px] text-[#a3a3a3]\">هيفتح تيليجرام بالنص جاهز - ابعته للبوت.</p>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- Bot Code Panel (hidden until the bot button is tapped) -->\r\n        <div id=\"botCodePanel\" class=\"hidden space-y-3 pt-3 border-t border-neutral-800\">\r\n          <div id=\"botCodeQualityWrap\">\r\n            <label class=\"text-xs font-bold text-neutral-300 block mb-1.5\">اختر الجودة لإرسالها عبر البوت:</label>\r\n            <div id=\"botCodeQualitiesRow\" class=\"flex flex-wrap gap-2\"></div>\r\n          </div>\r\n          <div id=\"botCodeResult\" class=\"hidden text-center space-y-2\">\r\n            <p class=\"text-xs text-[#a3a3a3]\">أرسل هذا الكود للبوت (صالح لمدة ساعة):</p>\r\n            <p id=\"botCodeValue\" class=\"text-3xl font-black tracking-[0.3em] text-amber-400 select-all\" dir=\"ltr\">…</p>\r\n            <div class=\"flex gap-2 justify-center\">\r\n              <button id=\"btnCopyBotCode\" type=\"button\" class=\"min-h-[44px] px-4 py-2 rounded-md bg-[#232323] border border-[#737373] text-white text-xs font-bold\">📋 نسخ الكود</button>\r\n              <button id=\"btnOpenBotPlain\" type=\"button\" class=\"min-h-[44px] px-4 py-2 rounded-md bg-[#e50914] text-white text-xs font-bold\">🚀 فتح البوت</button>\r\n            </div>\r\n            <button id=\"btnBotDeepLink\" type=\"button\" class=\"min-h-[44px] px-3 text-xs text-neutral-300 underline\">أو: فتح البوت برابط مباشر للفيلم</button>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- Similar titles (stage D) -->\r\n        <div id=\"similarWrap\" class=\"hidden pt-3 border-t border-neutral-800\">\r\n          <h4 class=\"text-sm font-extrabold text-white mb-3\">🎬 أعمال شبه ده</h4>\r\n          <div id=\"similarRow\" class=\"flex gap-3 overflow-x-auto pb-2 scrollbar-hide\"></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <script>\r\n    const API_BASE = 'https://filmaty.hudhaifa-bio.workers.dev';\r\n    const TMDB_KEY = '15d2ea6d0dc1d476efbca3eba2b9bbfb';\r\n    const TMDB_BASE = 'https://api.themoviedb.org/3';\r\n    const IMG_BASE = 'https://image.tmdb.org/t/p/w500';\r\n\r\n    let currentItem = null;\r\n    let selectedSeason = 1;\r\n    let selectedEpisode = 1;\r\n    let debounceTimer = null;\r\n    // Last successful /api/resolve result, reused by the download button\r\n    // without a second request. { key: 'movie:550:0:0', data: {...} }\r\n    let lastResolved = null;\r\n    // Server + quality selection for the last resolved title/episode.\r\n    let currentServers = null;\r\n    let selectedServerIdx = 0;\r\n    let selectedQualityIdx = 0;\r\n\r\n    // Continue watching (stage A): resume positions + watched marks,\r\n    // kept in localStorage on this device only (no accounts). The TV\r\n    // page uses the exact same keys and the same shape.\r\n    const PROGRESS_KEY = 'filmaty:progress:v1';\r\n    const WATCHED_KEY = 'filmaty:watched:v1';\r\n    const MAX_PROGRESS_ITEMS = 20;\r\n    function progressKey(type, id, s, e) {\r\n      return `${type}:${id}:${s || 0}:${e || 0}`;\r\n    }\r\n    function readProgressStore() {\r\n      try { return JSON.parse(localStorage.getItem(PROGRESS_KEY) || '{}'); } catch (e) { return {}; }\r\n    }\r\n    function readWatchedStore() {\r\n      try { return JSON.parse(localStorage.getItem(WATCHED_KEY) || '{}'); } catch (e) { return {}; }\r\n    }\r\n    function getProgress(type, id, s, e) {\r\n      return readProgressStore()[progressKey(type, id, s, e)] || null;\r\n    }\r\n    function isWatched(type, id, s, e) {\r\n      return !!readWatchedStore()[progressKey(type, id, s, e)];\r\n    }\r\n    function saveProgressEntry(type, id, s, e, t, d, meta) {\r\n      if (!Number.isFinite(t) || t < 5) return;\r\n      const store = readProgressStore();\r\n      const key = progressKey(type, id, s, e);\r\n      store[key] = {\r\n        type, id, s: s || 0, e: e || 0,\r\n        t: Math.floor(t), d: Number.isFinite(d) && d > 0 ? Math.floor(d) : 0,\r\n        updated: Date.now(), title: meta.title || '', poster: meta.poster || '', kind: meta.kind || '',\r\n      };\r\n      const entries = Object.values(store).sort((a, b) => b.updated - a.updated).slice(0, MAX_PROGRESS_ITEMS);\r\n      const capped = {};\r\n      entries.forEach((en) => { capped[progressKey(en.type, en.id, en.s, en.e)] = en; });\r\n      try { localStorage.setItem(PROGRESS_KEY, JSON.stringify(capped)); } catch (e) {}\r\n    }\r\n    function clearProgressEntry(type, id, s, e) {\r\n      const store = readProgressStore();\r\n      delete store[progressKey(type, id, s, e)];\r\n      try { localStorage.setItem(PROGRESS_KEY, JSON.stringify(store)); } catch (e) {}\r\n    }\r\n    function markWatchedEntry(type, id, s, e) {\r\n      const store = readWatchedStore();\r\n      store[progressKey(type, id, s, e)] = Date.now();\r\n      const keys = Object.keys(store).sort((a, b) => store[b] - store[a]).slice(0, 200);\r\n      const capped = {};\r\n      keys.forEach((k) => { capped[k] = store[k]; });\r\n      try { localStorage.setItem(WATCHED_KEY, JSON.stringify(capped)); } catch (e) {}\r\n      clearProgressEntry(type, id, s, e);\r\n    }\r\n    function formatTime(sec) {\r\n      sec = Math.max(0, Math.floor(sec || 0));\r\n      const h = Math.floor(sec / 3600);\r\n      const m = Math.floor((sec % 3600) / 60);\r\n      const s = sec % 60;\r\n      return h > 0 ? `${h}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}` : `${m}:${String(s).padStart(2, '0')}`;\r\n    }\r\n    function getContinueItems() {\r\n      return Object.values(readProgressStore()).sort((a, b) => b.updated - a.updated).slice(0, 10);\r\n    }\r\n\r\n    // My list (stage B): titles the user saved to watch later, kept in\r\n    // localStorage on this device only (no accounts). Same keys on the\r\n    // TV page.\r\n    const MYLIST_KEY = 'filmaty:mylist:v1';\r\n    const MAX_MYLIST_ITEMS = 50;\r\n    function myListKey(type, id) {\r\n      return `${type}:${id}`;\r\n    }\r\n    function readMyListStore() {\r\n      try { return JSON.parse(localStorage.getItem(MYLIST_KEY) || '{}'); } catch (e) { return {}; }\r\n    }\r\n    function isInMyList(type, id) {\r\n      return !!readMyListStore()[myListKey(type, id)];\r\n    }\r\n    function toggleMyList(type, id, meta) {\r\n      const store = readMyListStore();\r\n      const key = myListKey(type, id);\r\n      if (store[key]) {\r\n        delete store[key];\r\n        try { localStorage.setItem(MYLIST_KEY, JSON.stringify(store)); } catch (e) {}\r\n        return false;\r\n      }\r\n      store[key] = { type, id, title: meta.title || '', poster: meta.poster || '', kind: meta.kind || '', added: Date.now() };\r\n      const entries = Object.values(store).sort((a, b) => b.added - a.added).slice(0, MAX_MYLIST_ITEMS);\r\n      const capped = {};\r\n      entries.forEach((en) => { capped[myListKey(en.type, en.id)] = en; });\r\n      try { localStorage.setItem(MYLIST_KEY, JSON.stringify(capped)); } catch (e) {}\r\n      return true;\r\n    }\r\n    function getMyListItems() {\r\n      return Object.values(readMyListStore()).sort((a, b) => b.added - a.added);\r\n    }\r\n\r\n    // Telegram Mini App initialization\r\n    if (window.Telegram && window.Telegram.WebApp) {\r\n      window.Telegram.WebApp.ready();\r\n      window.Telegram.WebApp.expand();\r\n    }\r\n\r\n    // Elements\r\n    const searchInput = document.getElementById('searchInput');\r\n    const clearSearch = document.getElementById('clearSearch');\r\n    const mediaGrid = document.getElementById('mediaGrid');\r\n    const sectionTitle = document.getElementById('sectionTitle');\r\n    const itemsCount = document.getElementById('itemsCount');\r\n    const mediaModal = document.getElementById('mediaModal');\r\n    const closeModal = document.getElementById('closeModal');\r\n    const filterBtns = document.querySelectorAll('.filter-btn');\r\n\r\n    // Modal elements\r\n    const modalPoster = document.getElementById('modalPoster');\r\n    const modalTitle = document.getElementById('modalTitle');\r\n    const modalRating = document.getElementById('modalRating');\r\n    const modalYear = document.getElementById('modalYear');\r\n    const modalKind = document.getElementById('modalKind');\r\n    const modalStory = document.getElementById('modalStory');\r\n    const seriesControls = document.getElementById('seriesControls');\r\n    const seasonSelect = document.getElementById('seasonSelect');\r\n    const episodesGrid = document.getElementById('episodesGrid');\r\n    const playerContainer = document.getElementById('playerContainer');\r\n    const videoIframe = document.getElementById('videoIframe');\r\n    const videoNative = document.getElementById('videoNative');\r\n    const playerStatus = document.getElementById('playerStatus');\r\n    const btnPlayInApp = document.getElementById('btnPlayInApp');\r\n    const btnDirectDownload = document.getElementById('btnDirectDownload');\r\n    const btnOpenInBot = document.getElementById('btnOpenInBot');\r\n\r\n    // Home: featured hero billboard, most-watched first, then top-rated, with year filter chips.\r\n    // The grid view (search / discover / filters) hides these sections.\r\n    let homeData = null; // { mostWatched, topRated }\r\n    let homeYearFilter = 'all';\r\n    let heroItem = null;\r\n\r\n    function showGridView() {\r\n      const hero = document.getElementById('heroBanner');\r\n      if (hero) hero.classList.add('hidden');\r\n      document.getElementById('homeSections').classList.add('hidden');\r\n      document.getElementById('gridHeader').classList.remove('hidden');\r\n      mediaGrid.classList.remove('hidden');\r\n    }\r\n\r\n    function showHomeView() {\r\n      mediaGrid.classList.add('hidden');\r\n      document.getElementById('gridHeader').classList.add('hidden');\r\n      document.getElementById('homeSections').classList.remove('hidden');\r\n      const hero = document.getElementById('heroBanner');\r\n      if (hero && heroItem) hero.classList.remove('hidden');\r\n    }\r\n\r\n    function renderHeroBanner() {\r\n      const hero = document.getElementById('heroBanner');\r\n      if (!hero || !homeData) return;\r\n      const pool = [...(homeData.mostWatched || []), ...(homeData.topRated || [])];\r\n      heroItem = pool.find((i) => i && (i.backdrop_path || i.poster_path)) || pool[0] || null;\r\n      if (!heroItem) {\r\n        hero.classList.add('hidden');\r\n        return;\r\n      }\r\n      const type = heroItem.media_type === 'tv' || (!heroItem.media_type && heroItem.name) ? 'tv' : 'movie';\r\n      const title = heroItem.title || heroItem.name || '';\r\n      const date = heroItem.release_date || heroItem.first_air_date || '';\r\n      const year = date ? date.slice(0, 4) : '';\r\n      const rating = heroItem.vote_average ? heroItem.vote_average.toFixed(1) : '8.0';\r\n      const imgPath = heroItem.backdrop_path\r\n        ? `https://image.tmdb.org/t/p/w1280${heroItem.backdrop_path}`\r\n        : `${IMG_BASE}${heroItem.poster_path}`;\r\n      const heroImg = document.getElementById('heroImg');\r\n      heroImg.src = imgPath;\r\n      heroImg.alt = title;\r\n      document.getElementById('heroTitle').innerText = title;\r\n      document.getElementById('heroKind').innerText = type === 'tv' ? 'مسلسل' : 'فيلم';\r\n      document.getElementById('heroYear').innerText = year;\r\n      document.getElementById('heroRating').innerText = `★ ${rating}`;\r\n      document.getElementById('heroOverview').innerText = heroItem.overview || '';\r\n      if (!document.getElementById('homeSections').classList.contains('hidden')) {\r\n        hero.classList.remove('hidden');\r\n      }\r\n    }\r\n\r\n    document.getElementById('heroInfoBtn').addEventListener('click', () => {\r\n      if (!heroItem) return;\r\n      const type = heroItem.media_type === 'tv' || (!heroItem.media_type && heroItem.name) ? 'tv' : 'movie';\r\n      openDetails(heroItem.id, type);\r\n    });\r\n    document.getElementById('heroPlayBtn').addEventListener('click', async () => {\r\n      if (!heroItem) return;\r\n      const type = heroItem.media_type === 'tv' || (!heroItem.media_type && heroItem.name) ? 'tv' : 'movie';\r\n      await openDetails(heroItem.id, type);\r\n      const entry = currentResumeEntry();\r\n      pendingResume = entry ? entry.t : null;\r\n      playActiveStream();\r\n    });\r\n\r\n    async function loadHome() {\r\n      showHomeView();\r\n      const sectionsEl = document.getElementById('homeSections');\r\n      sectionsEl.innerHTML = '<div class=\"animate-pulse bg-[#181818] rounded-xl h-64 border border-neutral-800\"></div>';\r\n      try {\r\n        const [homeRes, airingRes, upcomingRes] = await Promise.all([\r\n          fetch(`${API_BASE}/api/home`),\r\n          fetch(`${TMDB_BASE}/tv/airing_today?api_key=${TMDB_KEY}&language=ar`).catch(() => null),\r\n          fetch(`${TMDB_BASE}/movie/upcoming?api_key=${TMDB_KEY}&language=ar`).catch(() => null),\r\n        ]);\r\n        const data = await homeRes.json();\r\n        // New episodes + coming soon (stage H): TMDB direct, each\r\n        // failure degrades to an empty row instead of breaking home.\r\n        const airing = airingRes ? await airingRes.json().catch(() => null) : null;\r\n        const upcoming = upcomingRes ? await upcomingRes.json().catch(() => null) : null;\r\n        homeData = {\r\n          mostWatched: data.mostWatched || [],\r\n          topRated: data.topRated || [],\r\n          newEpisodes: ((airing?.results || []).slice(0, 20)).map((i) => ({ ...i, media_type: 'tv' })),\r\n          upcoming: ((upcoming?.results || []).slice(0, 20)).map((i) => ({ ...i, media_type: 'movie' })),\r\n        };\r\n        homeYearFilter = 'all';\r\n        renderHeroBanner();\r\n        renderHomeSections();\r\n      } catch (e) {\r\n        sectionsEl.innerHTML = `<div class=\"text-center py-12 text-[#a3a3a3] text-sm font-semibold\">تعذر جلب البيانات. يرجى التحقق من اتصالك.</div>`;\r\n      }\r\n    }\r\n\r\n    function homeYearOf(item) {\r\n      const date = item.release_date || item.first_air_date || '';\r\n      return date ? Number(date.slice(0, 4)) : null;\r\n    }\r\n\r\n    function filterHomeList(items) {\r\n      if (homeYearFilter === 'all') return items;\r\n      if (homeYearFilter === 'older') {\r\n        return items.filter((i) => { const y = homeYearOf(i); return y && y <= 2022; });\r\n      }\r\n      const year = Number(homeYearFilter);\r\n      return items.filter((i) => homeYearOf(i) === year);\r\n    }\r\n\r\n    function renderHomeSections() {\r\n      const sectionsEl = document.getElementById('homeSections');\r\n      if (!homeData) return;\r\n      const years = [\r\n        { value: 'all', label: 'الكل' },\r\n        { value: '2026', label: '2026' },\r\n        { value: '2025', label: '2025' },\r\n        { value: '2024', label: '2024' },\r\n        { value: '2023', label: '2023' },\r\n        { value: 'older', label: 'أقدم' },\r\n      ];\r\n      const chips = years.map((y) => `\r\n        <button type=\"button\" data-year=\"${y.value}\" class=\"home-year-chip min-h-[44px] whitespace-nowrap px-4 py-2 rounded-md border transition text-xs font-bold ${homeYearFilter === y.value ? 'bg-[#e50914] border-[#e50914] text-white' : 'bg-[#232323] border-[#737373] text-neutral-200 hover:border-white'}\">${y.label}</button>\r\n      `).join('');\r\n      const mostWatched = filterHomeList(homeData.mostWatched);\r\n      const topRated = filterHomeList(homeData.topRated);\r\n      const emptyNote = (!mostWatched.length && !topRated.length)\r\n        ? '<div class=\"text-center py-12 text-[#a3a3a3] text-sm font-bold\">لا توجد أعمال في هذه السنة.</div>'\r\n        : '';\r\n      sectionsEl.innerHTML = `\r\n        ${continueSectionHtml(getContinueItems())}\r\n        ${myListSectionHtml(getMyListItems())}\r\n        <div class=\"flex flex-wrap gap-2 items-center\">\r\n          <span class=\"text-xs font-bold text-[#a3a3a3]\">السنة:</span>\r\n          ${chips}\r\n        </div>\r\n        ${homeSectionHtml('🔥 الأكثر مشاهدة', mostWatched, true)}\r\n        ${homeSectionHtml('⭐ الأعلى تقييمًا', topRated)}\r\n        ${homeSectionHtml('🆕 حلقات جديدة', homeData.newEpisodes || [])}\r\n        ${homeSectionHtml('📅 قريبًا', homeData.upcoming || [])}\r\n        ${emptyNote}\r\n      `;\r\n      sectionsEl.querySelectorAll('.home-year-chip').forEach((btn) => {\r\n        btn.addEventListener('click', () => {\r\n          homeYearFilter = btn.dataset.year;\r\n          renderHomeSections();\r\n        });\r\n      });\r\n    }\r\n\r\n    function homeSectionHtml(title, items, showRank = false) {\r\n      if (!items.length) return '';\r\n      return `\r\n        <section>\r\n          <h3 class=\"text-base sm:text-lg font-extrabold text-white mb-3\">${title}</h3>\r\n          <div class=\"flex gap-3 overflow-x-auto pb-2 scrollbar-hide\">\r\n            ${items.map((item, idx) => homeCardHtml(item, showRank && idx < 10 ? idx + 1 : 0)).join('')}\r\n          </div>\r\n        </section>\r\n      `;\r\n    }\r\n\r\n    function homeCardHtml(item, rankNum = 0) {\r\n      const title = (item.title || item.name || 'بدون عنوان').replace(/\"/g, '&quot;');\r\n      const date = item.release_date || item.first_air_date || '';\r\n      const year = date ? date.slice(0, 4) : '';\r\n      const rating = item.vote_average ? item.vote_average.toFixed(1) : '7.5';\r\n      const poster = item.poster_path ? `${IMG_BASE}${item.poster_path}` : 'https://placehold.co/300x450/181818/a3a3a3?text=No+Poster';\r\n      const kind = item.media_type === 'tv' ? 'مسلسل' : 'فيلم';\r\n      const badgeLeft = rankNum > 0\r\n        ? `<span class=\"absolute top-2 left-2 px-2 py-0.5 rounded bg-[#e50914] text-white text-[11px] font-black shadow\">#${rankNum}</span>`\r\n        : `<span class=\"absolute top-2 left-2 px-1.5 py-0.5 rounded bg-black/80 text-neutral-200 text-[10px] font-bold\">${kind}</span>`;\r\n      return `\r\n        <div role=\"button\" tabindex=\"0\" class=\"group cursor-pointer shrink-0 w-36 sm:w-44 bg-[#181818] rounded-md overflow-hidden border border-neutral-800 hover:border-neutral-400 sm:hover:scale-[1.03] transition duration-200\" onclick=\"openDetails(${item.id}, '${item.media_type || (item.name ? 'tv' : 'movie')}')\" onkeydown=\"if(event.key==='Enter'||event.key===' '){event.preventDefault();this.click();}\">\r\n          <div class=\"relative aspect-[2/3] bg-neutral-900 overflow-hidden\">\r\n            <img src=\"${poster}\" alt=\"${title}\" loading=\"lazy\" class=\"w-full h-full object-cover\" />\r\n            <span class=\"absolute top-2 right-2 px-1.5 py-0.5 rounded bg-black/80 text-amber-400 text-[11px] font-extrabold\">★ ${rating}</span>\r\n            ${badgeLeft}\r\n          </div>\r\n          <div class=\"p-2.5 bg-[#181818]\">\r\n            <h4 class=\"text-xs font-bold text-white truncate\">${title}</h4>\r\n            <div class=\"flex items-center justify-between mt-1 text-[11px] text-[#a3a3a3] font-medium\">\r\n              <span>${year || kind}</span>\r\n              <span>${year ? kind : ''}</span>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      `;\r\n    }\r\n\r\n    // Continue watching row (stage A): personal, so it is NOT filtered\r\n    // by the year chips. Cards carry a progress bar and \"أكمل من M:SS\";\r\n    // tapping one opens the title at the saved season/episode and plays\r\n    // from the saved position.\r\n    function continueSectionHtml(items) {\r\n      if (!items.length) return '';\r\n      return `\r\n        <section>\r\n          <h3 class=\"text-base sm:text-lg font-extrabold text-white mb-3\">▶ أكمل المشاهدة</h3>\r\n          <div class=\"flex gap-3 overflow-x-auto pb-2 scrollbar-hide\">\r\n            ${items.map(continueCardHtml).join('')}\r\n          </div>\r\n        </section>\r\n      `;\r\n    }\r\n\r\n    function continueCardHtml(entry) {\r\n      const pct = entry.d > 0 ? Math.min(100, Math.round((entry.t / entry.d) * 100)) : 0;\r\n      const poster = entry.poster || 'https://placehold.co/300x450/181818/a3a3a3?text=No+Poster';\r\n      const epLabel = entry.type === 'tv' ? ` • حلقة ${entry.e}` : '';\r\n      const title = (entry.title || 'بدون عنوان').replace(/\"/g, '&quot;');\r\n      return `\r\n        <div role=\"button\" tabindex=\"0\" class=\"group cursor-pointer shrink-0 w-36 sm:w-44 bg-[#181818] rounded-md overflow-hidden border border-neutral-800 hover:border-neutral-400 sm:hover:scale-[1.03] transition duration-200\" onclick=\"openContinueEntry('${entry.type}', ${entry.id}, ${entry.s}, ${entry.e})\" onkeydown=\"if(event.key==='Enter'||event.key===' '){event.preventDefault();this.click();}\">\r\n          <div class=\"relative aspect-[2/3] bg-neutral-900 overflow-hidden\">\r\n            <img src=\"${poster}\" alt=\"${title}\" loading=\"lazy\" class=\"w-full h-full object-cover\" />\r\n            <span class=\"absolute bottom-0 right-0 left-0 h-1.5 bg-black/75\"><span class=\"block h-full bg-[#e50914]\" style=\"width:${pct}%\"></span></span>\r\n          </div>\r\n          <div class=\"p-2.5 bg-[#181818]\">\r\n            <h4 class=\"text-xs font-bold text-white truncate\">${title}${epLabel}</h4>\r\n            <div class=\"flex items-center justify-between mt-1 text-[11px] text-[#a3a3a3] font-medium\">\r\n              <span>أكمل من ${formatTime(entry.t)}</span>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      `;\r\n    }\r\n\r\n    async function openContinueEntry(type, id, s, e) {\r\n      await openDetails(id, type, type === 'tv' ? s : null, type === 'tv' ? e : null);\r\n      if (type === 'tv' && currentItem) {\r\n        const seasons = (currentItem.seasons || []).filter((x) => x.season_number > 0);\r\n        if (seasons.some((x) => x.season_number === s)) {\r\n          selectedSeason = s;\r\n          seasonSelect.value = String(s);\r\n          const season = seasons.find((x) => x.season_number === s);\r\n          renderEpisodes(season?.episode_count || 10);\r\n        }\r\n        selectedEpisode = e;\r\n        document.querySelectorAll('.ep-btn').forEach((b, i) => {\r\n          const on = i + 1 === e;\r\n          b.classList.toggle('bg-[#e50914]', on);\r\n          b.classList.toggle('border-[#e50914]', on);\r\n          b.classList.toggle('text-white', on);\r\n          b.classList.toggle('bg-[#232323]', !on);\r\n          b.classList.toggle('border-[#737373]', !on);\r\n          b.classList.toggle('text-neutral-200', !on);\r\n        });\r\n        updateResumeButton();\r\n      }\r\n      const entry = currentResumeEntry();\r\n      pendingResume = entry ? entry.t : null;\r\n      playActiveStream();\r\n    }\r\n\r\n    // My list row (stage B): tapping a card opens its details.\r\n    function myListSectionHtml(items) {\r\n      if (!items.length) return '';\r\n      return `\r\n        <section>\r\n          <h3 class=\"text-base sm:text-lg font-extrabold text-white mb-3\">❤️ قائمتي</h3>\r\n          <div class=\"flex gap-3 overflow-x-auto pb-2 scrollbar-hide\">\r\n            ${items.map(myListCardHtml).join('')}\r\n          </div>\r\n        </section>\r\n      `;\r\n    }\r\n\r\n    function myListCardHtml(entry) {\r\n      const poster = entry.poster || 'https://placehold.co/300x450/181818/a3a3a3?text=No+Poster';\r\n      const title = (entry.title || 'بدون عنوان').replace(/\"/g, '&quot;');\r\n      return `\r\n        <div role=\"button\" tabindex=\"0\" class=\"group cursor-pointer shrink-0 w-36 sm:w-44 bg-[#181818] rounded-md overflow-hidden border border-neutral-800 hover:border-neutral-400 sm:hover:scale-[1.03] transition duration-200\" onclick=\"openDetails(${entry.id}, '${entry.type}')\" onkeydown=\"if(event.key==='Enter'||event.key===' '){event.preventDefault();this.click();}\">\r\n          <div class=\"relative aspect-[2/3] bg-neutral-900 overflow-hidden\">\r\n            <img src=\"${poster}\" alt=\"${title}\" loading=\"lazy\" class=\"w-full h-full object-cover\" />\r\n          </div>\r\n          <div class=\"p-2.5 bg-[#181818]\">\r\n            <h4 class=\"text-xs font-bold text-white truncate\">${title}</h4>\r\n            <div class=\"flex items-center justify-between mt-1 text-[11px] text-[#a3a3a3] font-medium\">\r\n              <span>${entry.type === 'tv' ? 'مسلسل' : 'فيلم'}</span>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      `;\r\n    }\r\n\r\n    // The My list button in the details modal: toggles the current title.\r\n    function updateMyListButton() {\r\n      const btn = document.getElementById('btnMyList');\r\n      if (!btn || !currentItem) return;\r\n      const type = currentItem.media_type === 'tv' ? 'tv' : 'movie';\r\n      btn.innerHTML = isInMyList(type, currentItem.id) ? '❤️ في قائمتي — إزالة' : '🤍 أضف لقائمتي';\r\n    }\r\n\r\n    // Search suggestions + recent searches (stage E): as the user types,\r\n    // the top 6 live results appear under the search box; tapping one\r\n    // opens its details. Focusing an empty box shows recent searches\r\n    // (localStorage, newest first, max 8).\r\n    const RECENT_SEARCHES_KEY = 'filmaty:recent-searches:v1';\r\n    const searchSuggest = document.getElementById('searchSuggest');\r\n    let suggestTimer = null;\r\n    let suggestSeq = 0;\r\n    function readRecentSearches() {\r\n      try { return JSON.parse(localStorage.getItem(RECENT_SEARCHES_KEY) || '[]'); } catch (e) { return []; }\r\n    }\r\n    function saveRecentSearch(q) {\r\n      q = q.trim();\r\n      if (!q) return;\r\n      const list = readRecentSearches().filter((x) => x !== q);\r\n      list.unshift(q);\r\n      try { localStorage.setItem(RECENT_SEARCHES_KEY, JSON.stringify(list.slice(0, 8))); } catch (e) {}\r\n    }\r\n    function hideSuggest() {\r\n      searchSuggest.classList.add('hidden');\r\n      searchSuggest.innerHTML = '';\r\n    }\r\n    function renderSuggestItems(items, isRecent) {\r\n      if (!items.length) { hideSuggest(); return; }\r\n      const title = isRecent ? '🕘 بحثات أخيرة' : '💡 اقتراحات';\r\n      searchSuggest.innerHTML = `\r\n        <p class=\"px-4 pt-3 pb-1 text-[11px] font-extrabold text-slate-400\">${title}</p>\r\n        ${items.map((it) => {\r\n          if (isRecent) {\r\n            const q = String(it).replace(/\"/g, '&quot;');\r\n            return `<button class=\"suggest-item w-full text-right px-4 py-2.5 text-sm font-bold text-white hover:bg-slate-800 transition flex items-center gap-2\" data-query=\"${q}\"><span>🕘</span><span class=\"truncate\">${q}</span></button>`;\r\n          }\r\n          const name = (it.title || it.name || 'بدون عنوان').replace(/\"/g, '&quot;');\r\n          const date = it.release_date || it.first_air_date || '';\r\n          const year = date ? date.slice(0, 4) : '';\r\n          const kind = (it.media_type || (it.name ? 'tv' : 'movie')) === 'tv' ? 'مسلسل' : 'فيلم';\r\n          return `<button class=\"suggest-item w-full text-right px-4 py-2.5 text-sm font-bold text-white hover:bg-slate-800 transition flex items-center justify-between gap-2\" data-id=\"${it.id}\" data-type=\"${it.media_type || (it.name ? 'tv' : 'movie')}\"><span class=\"truncate\">${name}</span><span class=\"text-[11px] text-slate-400 shrink-0\">${kind} ${year}</span></button>`;\r\n        }).join('')}\r\n      `;\r\n      searchSuggest.classList.remove('hidden');\r\n      searchSuggest.querySelectorAll('.suggest-item').forEach((btn) => {\r\n        btn.addEventListener('click', () => {\r\n          hideSuggest();\r\n          if (btn.dataset.query) {\r\n            searchInput.value = btn.dataset.query;\r\n            clearSearch.classList.remove('hidden');\r\n            executeSearch(btn.dataset.query);\r\n            return;\r\n          }\r\n          openDetails(Number(btn.dataset.id), btn.dataset.type);\r\n        });\r\n      });\r\n    }\r\n    async function fetchSuggest(q) {\r\n      const seq = ++suggestSeq;\r\n      try {\r\n        const res = await fetch(`${API_BASE}/api/search?q=${encodeURIComponent(q)}`);\r\n        const data = await res.json();\r\n        if (seq !== suggestSeq) return;\r\n        if (searchInput.value.trim() !== q) return;\r\n        renderSuggestItems((data.results || []).filter((i) => !i.providerUrl).slice(0, 6), false);\r\n      } catch (e) {}\r\n    }\r\n    searchInput.addEventListener('focus', () => {\r\n      if (!searchInput.value.trim()) renderSuggestItems(readRecentSearches(), true);\r\n    });\r\n    searchInput.addEventListener('keydown', (e) => { if (e.key === 'Escape') hideSuggest(); });\r\n    document.addEventListener('click', (e) => {\r\n      if (!searchSuggest.contains(e.target) && e.target !== searchInput) hideSuggest();\r\n    });\r\n\r\n    // Search function with Debounce\r\n    searchInput.addEventListener('input', (e) => {\r\n      const q = e.target.value.trim();\r\n      clearSearch.classList.toggle('hidden', !q);\r\n      clearTimeout(debounceTimer);\r\n      clearTimeout(suggestTimer);\r\n      if (!q) {\r\n        loadHome();\r\n        hideSuggest();\r\n        return;\r\n      }\r\n      suggestTimer = setTimeout(() => fetchSuggest(q), 250);\r\n      debounceTimer = setTimeout(() => executeSearch(q), 350);\r\n    });\r\n\r\n    clearSearch.addEventListener('click', () => {\r\n      searchInput.value = '';\r\n      clearSearch.classList.add('hidden');\r\n      hideSuggest();\r\n      loadHome();\r\n    });\r\n\r\n    // Search via the Worker: TMDB in Arabic + English merged, with a\r\n    // provider fallback when TMDB returns nothing.\r\n    async function executeSearch(query) {\r\n      saveRecentSearch(query);\r\n      hideSuggest();\r\n      renderLoading();\r\n      try {\r\n        const res = await fetch(`${API_BASE}/api/search?q=${encodeURIComponent(query)}`);\r\n        const data = await res.json();\r\n        renderCards(data.results || [], `🔍 نتائج البحث عن: \"${query}\"`);\r\n      } catch (e) {\r\n        showError('تعذر إتمام البحث. حاول مرة أخرى.');\r\n      }\r\n    }\r\n\r\n    // Side drawer (hamburger menu). Slides in from the right (RTL start\r\n    // side); the overlay or the ✕ button closes it. Full-height and\r\n    // scrollable so it works on a 390px phone.\r\n    const menuBtn = document.getElementById('menuBtn');\r\n    const sideDrawer = document.getElementById('sideDrawer');\r\n    const drawerOverlay = document.getElementById('drawerOverlay');\r\n    const drawerClose = document.getElementById('drawerClose');\r\n\r\n    function openDrawer() {\r\n      sideDrawer.classList.remove('translate-x-full');\r\n      drawerOverlay.classList.remove('hidden');\r\n      document.body.classList.add('overflow-hidden');\r\n    }\r\n\r\n    function closeDrawer() {\r\n      sideDrawer.classList.add('translate-x-full');\r\n      drawerOverlay.classList.add('hidden');\r\n      document.body.classList.remove('overflow-hidden');\r\n    }\r\n\r\n    menuBtn.addEventListener('click', openDrawer);\r\n    drawerClose.addEventListener('click', closeDrawer);\r\n    drawerOverlay.addEventListener('click', closeDrawer);\r\n\r\n    // Expandable drawer groups (movies / series language lists, and the\r\n    // nested «لغات أخرى» sub-groups inside each). The button's\r\n    // data-group names the sub-list: drawer-<group>.\r\n    document.querySelectorAll('.drawer-group-btn').forEach((btn) => {\r\n      btn.addEventListener('click', () => {\r\n        const sub = document.getElementById(`drawer-${btn.dataset.group}`);\r\n        const arrow = btn.querySelector('.drawer-arrow');\r\n        const opening = sub.classList.contains('hidden');\r\n        sub.classList.toggle('hidden');\r\n        if (arrow) arrow.textContent = opening ? '▴' : '▾';\r\n      });\r\n    });\r\n\r\n    // Language names for browse titles: «🎬 أفلام عربية», «📺 مسلسلات هندية».\r\n    const LANG_LABELS = {\r\n      ar: 'عربية', en: 'إنجليزية', hi: 'هندية', tr: 'تركية',\r\n      ko: 'كورية', es: 'إسبانية', fr: 'فرنسية', ja: 'يابانية',\r\n    };\r\n\r\n    // Browse via the Worker (/api/browse) — all browsing goes through the\r\n    // backend now; the old direct-browser TMDB discover calls are gone.\r\n    async function loadBrowse(params, title) {\r\n      renderLoading();\r\n      try {\r\n        const qs = new URLSearchParams(params);\r\n        const res = await fetch(`${API_BASE}/api/browse?${qs.toString()}`);\r\n        const data = await res.json();\r\n        renderCards(data.results || [], title);\r\n      } catch (e) {\r\n        showError('تعذر جلب البيانات.');\r\n      }\r\n    }\r\n\r\n    // English (American) browses with lang=en + origin=US so the list\r\n    // is US-origin English content, not every English-language title.\r\n    function loadBrowseLanguage(type, lang, origin) {\r\n      const kind = type === 'tv' ? '📺 مسلسلات' : '🎬 أفلام';\r\n      const params = { type, lang, sort: 'popular', page: '1' };\r\n      if (origin) params.origin = origin;\r\n      loadBrowse(\r\n        params,\r\n        `${kind} ${LANG_LABELS[lang] || lang}${origin ? ' (أمريكية)' : ''}`,\r\n      );\r\n    }\r\n\r\n    // Top-rated: top-rated movies + top-rated series, one grid merged by\r\n    // vote_average desc.\r\n    async function loadTopRated() {\r\n      renderLoading();\r\n      try {\r\n        const [movies, tv] = await Promise.all([\r\n          fetch(`${API_BASE}/api/browse?type=movie&sort=top_rated&page=1`).then((r) => r.json()),\r\n          fetch(`${API_BASE}/api/browse?type=tv&sort=top_rated&page=1`).then((r) => r.json()),\r\n        ]);\r\n        const merged = [...(movies.results || []), ...(tv.results || [])]\r\n          .sort((a, b) => (b.vote_average || 0) - (a.vote_average || 0));\r\n        renderCards(merged, '⭐ الأعلى تقييمًا');\r\n      } catch (e) {\r\n        showError('تعذر جلب البيانات.');\r\n      }\r\n    }\r\n\r\n    function syncHeaderNavFilter(activeFilter) {\r\n      document.querySelectorAll('.nav-filter-link').forEach((link) => {\r\n        const isMatch = link.dataset.navFilter === activeFilter;\r\n        link.classList.toggle('text-white', isMatch);\r\n        link.classList.toggle('font-black', isMatch);\r\n        link.classList.toggle('text-neutral-300', !isMatch);\r\n        link.classList.toggle('font-semibold', !isMatch);\r\n      });\r\n    }\r\n\r\n    function clearActiveFilters() {\r\n      filterBtns.forEach((b) => {\r\n        b.classList.remove('bg-[#e50914]', 'border-[#e50914]', 'text-white');\r\n        b.classList.add('bg-[#232323]', 'border-[#737373]', 'text-neutral-200');\r\n      });\r\n      syncHeaderNavFilter('');\r\n    }\r\n\r\n    // Drawer language items.\r\n    document.querySelectorAll('.drawer-lang').forEach((btn) => {\r\n      btn.addEventListener('click', () => {\r\n        clearActiveFilters();\r\n        closeDrawer();\r\n        loadBrowseLanguage(btn.dataset.type, btn.dataset.lang, btn.dataset.origin);\r\n      });\r\n    });\r\n\r\n    document.getElementById('drawerTopRated').addEventListener('click', () => {\r\n      clearActiveFilters();\r\n      closeDrawer();\r\n      loadTopRated();\r\n    });\r\n    document.getElementById('drawerMarvel').addEventListener('click', () => {\r\n      clearActiveFilters();\r\n      closeDrawer();\r\n      loadBrowse({ type: 'movie', collection: 'marvel', sort: 'popular', page: '1' }, '🦸‍♂️ مارفل');\r\n    });\r\n    document.getElementById('drawerNetflix').addEventListener('click', () => {\r\n      clearActiveFilters();\r\n      closeDrawer();\r\n      loadBrowse({ type: 'movie', collection: 'netflix', sort: 'popular', page: '1' }, '🔴 نتفليكس');\r\n    });\r\n\r\n    // Category filter click handler: each tab has its own home.\r\n    filterBtns.forEach(btn => {\r\n      btn.addEventListener('click', () => {\r\n        filterBtns.forEach(b => {\r\n          b.classList.remove('bg-[#e50914]', 'border-[#e50914]', 'text-white');\r\n          b.classList.add('bg-[#232323]', 'border-[#737373]', 'text-neutral-200');\r\n        });\r\n        btn.classList.remove('bg-[#232323]', 'border-[#737373]', 'text-neutral-200');\r\n        btn.classList.add('bg-[#e50914]', 'border-[#e50914]', 'text-white');\r\n\r\n        const filter = btn.dataset.filter;\r\n        syncHeaderNavFilter(filter);\r\n        searchInput.value = '';\r\n        clearSearch.classList.add('hidden');\r\n\r\n        if (filter === 'trending') loadHome();\r\n        else if (filter === 'movie') loadBrowse({ type: 'movie', sort: 'popular', page: '1' }, '🎬 أحدث الأفلام');\r\n        else if (filter === 'tv') loadBrowse({ type: 'tv', sort: 'popular', page: '1' }, '📺 أحدث المسلسلات');\r\n        else if (filter === 'marvel') loadBrowse({ type: 'movie', collection: 'marvel', sort: 'popular', page: '1' }, '🦸‍♂️ مارفل');\r\n        else if (filter === 'netflix') loadBrowse({ type: 'movie', collection: 'netflix', sort: 'popular', page: '1' }, '🔴 نتفليكس');\r\n      });\r\n    });\r\n\r\n    document.querySelectorAll('.nav-filter-link').forEach((link) => {\r\n      link.addEventListener('click', () => {\r\n        const target = document.querySelector(`.filter-btn[data-filter=\"${link.dataset.navFilter}\"]`);\r\n        if (target) target.click();\r\n      });\r\n    });\r\n\r\n    const brandHomeBtn = document.getElementById('brandHomeBtn');\r\n    if (brandHomeBtn) {\r\n      const goHome = () => {\r\n        const trendingBtn = document.querySelector('.filter-btn[data-filter=\"trending\"]');\r\n        if (trendingBtn) trendingBtn.click(); else loadHome();\r\n      };\r\n      brandHomeBtn.addEventListener('click', goHome);\r\n      brandHomeBtn.addEventListener('keydown', (e) => {\r\n        if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); goHome(); }\r\n      });\r\n    }\r\n\r\n    function renderLoading() {\r\n      showGridView();\r\n      mediaGrid.innerHTML = Array(12).fill(0).map(() => `\r\n        <div class=\"animate-pulse bg-[#181818] rounded-md aspect-[2/3] border border-neutral-800\"></div>\r\n      `).join('');\r\n    }\r\n\r\n    function showError(msg) {\r\n      showGridView();\r\n      mediaGrid.innerHTML = `<div class=\"col-span-full text-center py-12 text-[#a3a3a3] text-sm font-semibold\">${msg}</div>`;\r\n    }\r\n\r\n    function renderCards(items, title) {\r\n      sectionTitle.innerHTML = title;\r\n      itemsCount.innerText = `${items.length} عمل`;\r\n\r\n      if (!items.length) {\r\n        mediaGrid.innerHTML = `\r\n          <div class=\"col-span-full text-center py-16 text-[#a3a3a3]\">\r\n            <p class=\"text-3xl mb-2\">🍿</p>\r\n            <p class=\"text-sm font-bold\">لم يتم العثور على نتائج مطابقة.</p>\r\n          </div>`;\r\n        return;\r\n      }\r\n\r\n      mediaGrid.innerHTML = items.map(item => {\r\n        const rawTitle = item.title || item.name || 'بدون عنوان';\r\n        const safeTitle = rawTitle.replace(/\"/g, '&quot;');\r\n        const date = item.release_date || item.first_air_date || '';\r\n        const year = date ? date.slice(0, 4) : '';\r\n        const rating = item.vote_average ? item.vote_average.toFixed(1) : '7.5';\r\n        // Provider-only entries carry a full poster URL and a provider link\r\n        // (no TMDB id): prefer the full URL, and open the provider page.\r\n        const poster = item.poster || (item.poster_path ? `${IMG_BASE}${item.poster_path}` : 'https://placehold.co/300x450/181818/a3a3a3?text=No+Poster');\r\n        const kind = item.media_type === 'tv' ? 'مسلسل' : 'فيلم';\r\n        const click = item.providerUrl\r\n          ? `window.open('${item.providerUrl}', '_blank')`\r\n          : `openDetails(${item.id}, '${item.media_type || (item.name ? 'tv' : 'movie')}')`;\r\n        const metaRight = item.provider\r\n          ? `<span class=\"text-blue-400 font-semibold\">${item.provider} ↗</span>`\r\n          : `<span>${year ? kind : ''}</span>`;\r\n\r\n        return `\r\n          <div role=\"button\" tabindex=\"0\" class=\"group cursor-pointer bg-[#181818] rounded-md overflow-hidden border border-neutral-800 hover:border-neutral-400 sm:hover:scale-[1.03] transition duration-200\" onclick=\"${click}\" onkeydown=\"if(event.key==='Enter'||event.key===' '){event.preventDefault();this.click();}\">\r\n            <div class=\"relative aspect-[2/3] bg-neutral-900 overflow-hidden\">\r\n              <img src=\"${poster}\" alt=\"${safeTitle}\" loading=\"lazy\" class=\"w-full h-full object-cover\" />\r\n              <span class=\"absolute top-2 right-2 px-1.5 py-0.5 rounded bg-black/80 text-amber-400 text-[11px] font-extrabold\">★ ${rating}</span>\r\n              <span class=\"absolute top-2 left-2 px-1.5 py-0.5 rounded bg-black/80 text-neutral-200 text-[10px] font-bold\">${kind}</span>\r\n            </div>\r\n            <div class=\"p-2.5 bg-[#181818]\">\r\n              <h4 class=\"text-xs font-bold text-white truncate\">${safeTitle}</h4>\r\n              <div class=\"flex items-center justify-between mt-1 text-[11px] text-[#a3a3a3] font-medium\">\r\n                <span>${year || kind}</span>\r\n                ${metaRight}\r\n              </div>\r\n            </div>\r\n          </div>\r\n        `;\r\n      }).join('');\r\n    }\r\n\r\n    function getDownloadQualities(resolved) {\r\n      if (!resolved || !resolved.ok || !resolved.servers || !resolved.servers[0]) return [];\r\n      if (isEmbedServer(resolved.servers[0])) return [];\r\n      return (resolved.servers[0].qualities || []).filter((q) => q.download);\r\n    }\r\n\r\n    function syncDownloadButtonState(resolved) {\r\n      const label = document.getElementById('btnDirectDownloadLabel');\r\n      const icon = document.getElementById('btnDirectDownloadIcon');\r\n      if (!btnDirectDownload || !label || !icon) return;\r\n      if (!resolved) {\r\n        btnDirectDownload.setAttribute('aria-disabled', 'false');\r\n        btnDirectDownload.classList.remove('opacity-60');\r\n        icon.innerText = '⬇';\r\n        label.innerText = 'تحميل مباشر (.mp4)';\r\n        return;\r\n      }\r\n      if (getDownloadQualities(resolved).length > 0) {\r\n        btnDirectDownload.setAttribute('aria-disabled', 'false');\r\n        btnDirectDownload.classList.remove('opacity-60');\r\n        icon.innerText = '⬇';\r\n        label.innerText = 'تحميل مباشر (.mp4)';\r\n      } else {\r\n        btnDirectDownload.setAttribute('aria-disabled', 'true');\r\n        btnDirectDownload.classList.add('opacity-60');\r\n        icon.innerText = 'ℹ';\r\n        label.innerText = 'متاح مشاهدة أونلاين فقط';\r\n      }\r\n    }\r\n\r\n    function hideModalBackdrop() {\r\n      const wrap = document.getElementById('modalBackdropWrap');\r\n      if (wrap) wrap.classList.add('hidden');\r\n    }\r\n\r\n    let suppressHistorySync = false;\r\n\r\n    function buildShareUrl(item, s, e) {\r\n      const u = new URL(window.location.href);\r\n      ['movie', 'tv', 's', 'e', 'id', 'type'].forEach((k) => u.searchParams.delete(k));\r\n      u.hash = '';\r\n      if (item && item.id) {\r\n        if (item.media_type === 'tv') {\r\n          u.searchParams.set('tv', String(item.id));\r\n          u.searchParams.set('s', String(s || 1));\r\n          u.searchParams.set('e', String(e || 1));\r\n        } else {\r\n          u.searchParams.set('movie', String(item.id));\r\n        }\r\n      }\r\n      return u.toString();\r\n    }\r\n\r\n    function syncUrlWithModal(mode) {\r\n      if (suppressHistorySync) return;\r\n      try {\r\n        if (mode === 'clear' || !currentItem) {\r\n          const cleanUrl = buildShareUrl(null);\r\n          if (window.location.href !== cleanUrl) {\r\n            history.pushState(null, '', cleanUrl);\r\n          }\r\n          return;\r\n        }\r\n        const targetUrl = buildShareUrl(currentItem, selectedSeason, selectedEpisode);\r\n        if (window.location.href === targetUrl) return;\r\n        if (mode === 'push') {\r\n          history.pushState({ filmatyModal: true }, '', targetUrl);\r\n        } else {\r\n          history.replaceState({ filmatyModal: true }, '', targetUrl);\r\n        }\r\n      } catch (e) {}\r\n    }\r\n\r\n    async function shareCurrentMedia() {\r\n      if (!currentItem) return;\r\n      const url = buildShareUrl(currentItem, selectedSeason, selectedEpisode);\r\n      const title = currentItem.title || currentItem.name || 'فيلماتي';\r\n      const epText = currentItem.media_type === 'tv' ? ` - الموسم ${selectedSeason} الحلقة ${selectedEpisode}` : '';\r\n      if (typeof navigator.share === 'function') {\r\n        try {\r\n          await navigator.share({\r\n            title: `${title}${epText} | فيلماتي`,\r\n            text: `شاهد ${title}${epText} على فيلماتي`,\r\n            url,\r\n          });\r\n          return;\r\n        } catch (err) {\r\n          if (err && err.name === 'AbortError') return;\r\n        }\r\n      }\r\n      try {\r\n        await navigator.clipboard.writeText(url);\r\n        showToast('تم نسخ رابط المشاركة ✅');\r\n      } catch (err) {\r\n        const ta = document.createElement('textarea');\r\n        ta.value = url;\r\n        ta.setAttribute('readonly', '');\r\n        ta.style.position = 'fixed';\r\n        ta.style.opacity = '0';\r\n        document.body.appendChild(ta);\r\n        ta.select();\r\n        try {\r\n          document.execCommand('copy');\r\n          showToast('تم نسخ رابط المشاركة ✅');\r\n        } catch (e) {\r\n          showToast(url);\r\n        }\r\n        ta.remove();\r\n      }\r\n    }\r\n\r\n    // Modal Details Logic\r\n    async function openDetails(id, mediaType, wantSeason = null, wantEpisode = null) {\r\n      try {\r\n        const res = await fetch(`${TMDB_BASE}/${mediaType}/${id}?api_key=${TMDB_KEY}&language=ar`);\r\n        currentItem = await res.json();\r\n        currentItem.media_type = mediaType;\r\n\r\n        const title = currentItem.title || currentItem.name;\r\n        const date = currentItem.release_date || currentItem.first_air_date || '';\r\n        const year = date ? date.slice(0, 4) : '';\r\n        const rating = currentItem.vote_average ? currentItem.vote_average.toFixed(1) : '8.0';\r\n        const poster = currentItem.poster_path ? `${IMG_BASE}${currentItem.poster_path}` : 'https://placehold.co/300x450/181818/a3a3a3?text=Poster';\r\n\r\n        modalTitle.innerText = title;\r\n        modalPoster.src = poster;\r\n        modalRating.innerText = `★ ${rating}`;\r\n        modalYear.innerText = year;\r\n        modalKind.innerText = mediaType === 'tv' ? 'مسلسل' : 'فيلم';\r\n        modalStory.innerText = currentItem.overview || 'لا يتوفر وصف مختصر لهذا العمل حالياً.';\r\n\r\n        const backdropWrap = document.getElementById('modalBackdropWrap');\r\n        const backdropImg = document.getElementById('modalBackdropImg');\r\n        if (backdropWrap && backdropImg) {\r\n          const bPath = currentItem.backdrop_path\r\n            ? `https://image.tmdb.org/t/p/w1280${currentItem.backdrop_path}`\r\n            : (currentItem.poster_path ? poster : '');\r\n          if (bPath) {\r\n            backdropImg.src = bPath;\r\n            backdropImg.alt = title || '';\r\n            backdropWrap.classList.remove('hidden');\r\n          } else {\r\n            backdropWrap.classList.add('hidden');\r\n          }\r\n        }\r\n\r\n        // Player reset\r\n        resetPlayer();\r\n        playerContainer.classList.add('hidden');\r\n        updatePlayerToolbarVisibility(false);\r\n        document.getElementById('serverControls').classList.add('hidden');\r\n        document.getElementById('downloadPicker').classList.add('hidden');\r\n        document.getElementById('botCodePanel').classList.add('hidden');\r\n\r\n        if (mediaType === 'tv') {\r\n          seriesControls.classList.remove('hidden');\r\n          setupSeriesSeasons(currentItem, wantSeason, wantEpisode);\r\n        } else {\r\n          seriesControls.classList.add('hidden');\r\n          selectedSeason = 1;\r\n          selectedEpisode = 1;\r\n        }\r\n        document.getElementById('btnDownloadSeason').classList.toggle('hidden', mediaType !== 'tv');\r\n        document.getElementById('seasonDownloadPicker').classList.add('hidden');\r\n        document.getElementById('seasonDownloadProgress').classList.add('hidden');\r\n\r\n        const k = resolveKey(mediaType === 'tv' ? 'tv' : 'movie', currentItem.id, mediaType === 'tv' ? selectedSeason : undefined, mediaType === 'tv' ? selectedEpisode : undefined);\r\n        syncDownloadButtonState(lastResolved && lastResolved.key === k ? lastResolved.data : null);\r\n\r\n        mediaModal.classList.remove('hidden');\r\n        document.body.classList.add('overflow-hidden');\r\n        syncUrlWithModal('push');\r\n        updateResumeButton();\r\n        updateMyListButton();\r\n        loadTrailerAndSimilar(id, mediaType);\r\n      } catch (err) {\r\n        alert('تعذر فتح تفاصيل العمل.');\r\n      }\r\n    }\r\n\r\n    // Trailer + similar titles (stage D): fetched from TMDB after the\r\n    // details open. The trailer plays in the same iframe (YouTube is\r\n    // trusted, so no sandbox — embedwave re-adds its sandbox on play).\r\n    // A sequence guard drops stale responses when the user opens\r\n    // another title before the fetch lands.\r\n    let trailerKey = null;\r\n    let trailerLoadSeq = 0;\r\n    async function loadTrailerAndSimilar(id, mediaType) {\r\n      const loadId = ++trailerLoadSeq;\r\n      trailerKey = null;\r\n      const btn = document.getElementById('btnTrailer');\r\n      const wrap = document.getElementById('similarWrap');\r\n      const row = document.getElementById('similarRow');\r\n      btn.classList.add('hidden');\r\n      wrap.classList.add('hidden');\r\n      row.innerHTML = '';\r\n      try {\r\n        const [videosRes, similarRes] = await Promise.all([\r\n          fetch(`${TMDB_BASE}/${mediaType}/${id}/videos?api_key=${TMDB_KEY}&language=en-US`),\r\n          fetch(`${TMDB_BASE}/${mediaType}/${id}/similar?api_key=${TMDB_KEY}&language=ar`),\r\n        ]);\r\n        if (loadId !== trailerLoadSeq) return;\r\n        const videos = await videosRes.json().catch(() => null);\r\n        const trailer = (videos?.results || []).find((v) => v.site === 'YouTube' && v.type === 'Trailer');\r\n        if (trailer) { trailerKey = trailer.key; btn.classList.remove('hidden'); }\r\n        const similar = await similarRes.json().catch(() => null);\r\n        const items = (similar?.results || []).slice(0, 10);\r\n        if (items.length) {\r\n          row.innerHTML = items.map((it) => homeCardHtml(it, 0)).join('');\r\n          wrap.classList.remove('hidden');\r\n        }\r\n      } catch (e) {}\r\n    }\r\n\r\n    function setupSeriesSeasons(tv, wantSeason = null, wantEpisode = null) {\r\n      const seasons = (tv.seasons || []).filter(s => s.season_number > 0);\r\n      seasonSelect.innerHTML = seasons.map(s => `\r\n        <option value=\"${s.season_number}\">الموسم ${s.season_number} (${s.episode_count} حلقة)</option>\r\n      `).join('');\r\n\r\n      const targetS = wantSeason ? Number(wantSeason) : 0;\r\n      const matched = targetS ? seasons.find((s) => s.season_number === targetS) : null;\r\n      selectedSeason = matched ? matched.season_number : (seasons[0]?.season_number || 1);\r\n      seasonSelect.value = String(selectedSeason);\r\n      const currentSeasonObj = seasons.find((s) => s.season_number === selectedSeason) || seasons[0];\r\n      renderEpisodes(currentSeasonObj?.episode_count || 10, wantEpisode || 1);\r\n\r\n      seasonSelect.onchange = (e) => {\r\n        selectedSeason = Number(e.target.value);\r\n        const s = seasons.find(x => x.season_number === selectedSeason);\r\n        renderEpisodes(s?.episode_count || 10, 1);\r\n        syncUrlWithModal('replace');\r\n      };\r\n    }\r\n\r\n    function renderEpisodes(count, wantEpisode = 1) {\r\n      const targetEp = Number(wantEpisode) || 1;\r\n      selectedEpisode = targetEp >= 1 && targetEp <= count ? targetEp : 1;\r\n      currentSeasonEpisodeCount = count;\r\n      episodesGrid.innerHTML = Array.from({ length: count }, (_, i) => i + 1).map(epNum => {\r\n        const watched = currentItem && isWatched('tv', currentItem.id, selectedSeason, epNum);\r\n        const prog = currentItem ? getProgress('tv', currentItem.id, selectedSeason, epNum) : null;\r\n        const pct = prog && prog.d > 0 ? Math.min(100, Math.round((prog.t / prog.d) * 100)) : 0;\r\n        const active = epNum === selectedEpisode;\r\n        return `\r\n        <button type=\"button\" class=\"ep-btn relative overflow-hidden min-h-[44px] ${active ? 'bg-[#e50914] border-[#e50914] text-white' : 'bg-[#232323] border-[#737373] text-neutral-200'} rounded-md py-1.5 text-xs font-bold border hover:border-white transition\" onclick=\"selectEpisode(${epNum}, this)\">\r\n          ${watched ? '✓ ' : ''}حلقة ${epNum}\r\n          ${pct > 0 ? `<span class=\"absolute bottom-0 right-0 h-1 bg-emerald-400\" style=\"width:${pct}%\"></span>` : ''}\r\n        </button>\r\n      `; }).join('');\r\n      if (currentItem) {\r\n        const k = resolveKey('tv', currentItem.id, selectedSeason, selectedEpisode);\r\n        syncDownloadButtonState(lastResolved && lastResolved.key === k ? lastResolved.data : null);\r\n      }\r\n      updateResumeButton();\r\n    }\r\n\r\n    function selectEpisode(epNum, btn) {\r\n      selectedEpisode = epNum;\r\n      clearAutoNext();\r\n      document.querySelectorAll('.ep-btn').forEach(b => {\r\n        b.classList.remove('bg-[#e50914]', 'border-[#e50914]', 'text-white');\r\n        b.classList.add('bg-[#232323]', 'border-[#737373]', 'text-neutral-200');\r\n      });\r\n      btn.classList.remove('bg-[#232323]', 'border-[#737373]', 'text-neutral-200');\r\n      btn.classList.add('bg-[#e50914]', 'border-[#e50914]', 'text-white');\r\n      if (currentItem) {\r\n        const k = resolveKey('tv', currentItem.id, selectedSeason, selectedEpisode);\r\n        syncDownloadButtonState(lastResolved && lastResolved.key === k ? lastResolved.data : null);\r\n      }\r\n      syncUrlWithModal('replace');\r\n      updateResumeButton();\r\n\r\n      // Update active stream player if already open\r\n      if (!playerContainer.classList.contains('hidden')) {\r\n        const entry = currentResumeEntry();\r\n        pendingResume = entry ? entry.t : null;\r\n        playActiveStream();\r\n      }\r\n    }\r\n\r\n    function resolveKey(type, id, s, e) {\r\n      return `${type}:${id}:${s || 0}:${e || 0}`;\r\n    }\r\n\r\n    // Ask the Worker for the servers/qualities of a title. 25s timeout\r\n    // allows initial uncached provider sweep without dropping prematurely to EmbedWave.\r\n    async function fetchResolve(type, id, s, e) {\r\n      const params = new URLSearchParams({ type, id: String(id) });\r\n      if (s) params.set('s', String(s));\r\n      if (e) params.set('e', String(e));\r\n      const controller = new AbortController();\r\n      const timer = setTimeout(() => controller.abort(), 25000);\r\n      try {\r\n        const res = await fetch(`${API_BASE}/api/resolve?${params.toString()}`, { signal: controller.signal });\r\n        const data = await res.json().catch(() => null);\r\n        return data || null;\r\n      } catch (err) {\r\n        return null;\r\n      } finally {\r\n        clearTimeout(timer);\r\n      }\r\n    }\r\n\r\n    function showPlayerStatus(msg) {\r\n      playerStatus.innerText = msg;\r\n      playerStatus.classList.remove('hidden');\r\n    }\r\n\r\n    function hidePlayerStatus() {\r\n      playerStatus.classList.add('hidden');\r\n    }\r\n\r\n    function showIframeSpinner() {\r\n      const sp = document.getElementById('iframeSpinner');\r\n      if (sp) sp.classList.remove('hidden');\r\n    }\r\n\r\n    function hideIframeSpinner() {\r\n      const sp = document.getElementById('iframeSpinner');\r\n      if (sp) sp.classList.add('hidden');\r\n    }\r\n\r\n    function resetPlayer() {\r\n      trackProgress(true);\r\n      clearAutoNext();\r\n      nativeActive = false;\r\n      usingDirectCdn = false;\r\n      clearNativePlayTimeout();\r\n      videoNative.pause();\r\n      videoNative.removeAttribute('src');\r\n      videoNative.load();\r\n      videoNative.classList.add('hidden');\r\n      videoIframe.src = '';\r\n      videoIframe.classList.remove('hidden');\r\n      hideIframeSpinner();\r\n      hidePlayerStatus();\r\n    }\r\n\r\n    // Native-player failure handling: a dead stream (e.g. the CDN host is\r\n    // down) must fall back to the sandboxed embedwave iframe instead of\r\n    // leaving a broken black player — and the dead link must not be\r\n    // reused by the download button.\r\n    let nativeActive = false;\r\n    let nativePlayTimer = null;\r\n    let currentPlaybackRate = 1;\r\n    let usingDirectCdn = false;\r\n    let seekBadgeTimer = null;\r\n\r\n    function captureCurrentPlaybackTime() {\r\n      if (nativeActive && Number.isFinite(videoNative.currentTime) && videoNative.currentTime > 2) {\r\n        pendingResume = videoNative.currentTime;\r\n      }\r\n    }\r\n\r\n    function flashSeekIndicator(msg) {\r\n      const el = document.getElementById('seekIndicator');\r\n      if (!el) return;\r\n      el.innerText = msg;\r\n      el.classList.remove('hidden');\r\n      clearTimeout(seekBadgeTimer);\r\n      seekBadgeTimer = setTimeout(() => el.classList.add('hidden'), 900);\r\n    }\r\n\r\n    function seekNativeBy(delta) {\r\n      if (!nativeActive || videoNative.classList.contains('hidden')) return;\r\n      const dur = videoNative.duration;\r\n      const target = (videoNative.currentTime || 0) + delta;\r\n      videoNative.currentTime = Number.isFinite(dur) ? Math.max(0, Math.min(dur, target)) : Math.max(0, target);\r\n      flashSeekIndicator(delta < 0 ? `${delta} ث` : `+${delta} ث`);\r\n    }\r\n\r\n    function updatePlayerToolbarVisibility(isEmbed) {\r\n      const bar = document.getElementById('playerToolbar');\r\n      const nativeGroup = document.getElementById('nativeToolbarGroup');\r\n      const fsBtn = document.getElementById('btnFullscreen');\r\n      if (!bar || !nativeGroup) return;\r\n      if (playerContainer.classList.contains('hidden')) {\r\n        bar.classList.add('hidden');\r\n        bar.classList.remove('flex');\r\n        return;\r\n      }\r\n      bar.classList.remove('hidden');\r\n      bar.classList.add('flex');\r\n      nativeGroup.classList.toggle('hidden', !!isEmbed);\r\n      nativeGroup.classList.toggle('flex', !isEmbed);\r\n      if (fsBtn) fsBtn.classList.toggle('hidden', !!isEmbed);\r\n    }\r\n\r\n    function fallbackFromDirectToProxyOrNext(isTimeout) {\r\n      const server = selectedServer();\r\n      const quality = selectedQuality();\r\n      if (usingDirectCdn && server && !isEmbedServer(server) && quality && quality.stream && !quality._directFailed) {\r\n        quality._directFailed = true;\r\n        captureCurrentPlaybackTime();\r\n        usingDirectCdn = false;\r\n        playSelected();\r\n        return;\r\n      }\r\n      showPlayerStatus(\r\n        isTimeout\r\n          ? '⚠️ المصدر المباشر مش شغال - جاري التبديل لمشغّل بديل...'\r\n          : '⚠️ المصدر المباشر مش شغال - جاري تجربة مصدر آخر...'\r\n      );\r\n      tryNextQualityOrFallback();\r\n    }\r\n\r\n    function clearNativePlayTimeout() {\r\n      if (nativePlayTimer) { clearTimeout(nativePlayTimer); nativePlayTimer = null; }\r\n    }\r\n\r\n    function armNativePlayTimeout() {\r\n      clearNativePlayTimeout();\r\n      nativePlayTimer = setTimeout(() => {\r\n        if (!nativeActive) return;\r\n        // 45s with no playable data: the stream is dead, not just slow.\r\n        // The CDN can take well over 15s to deliver the first bytes on a\r\n        // cold start (verified live: Interstellar 1080p needed over 15s\r\n        // before readyState 2, then played fine) — a 15s timeout kept\r\n        // declaring healthy streams dead and cycling away from them.\r\n        if (videoNative.readyState < 2) {\r\n          fallbackFromDirectToProxyOrNext(true);\r\n        }\r\n      }, 45000);\r\n    }\r\n\r\n    videoNative.addEventListener('error', () => {\r\n      if (!nativeActive) return;\r\n      fallbackFromDirectToProxyOrNext(false);\r\n    });\r\n    videoNative.addEventListener('playing', clearNativePlayTimeout);\r\n    videoIframe.addEventListener('load', hideIframeSpinner);\r\n\r\n    // Continue watching: save the position while playing (throttled to\r\n    // every 5s), on pause, and when the page hides; mark watched at the\r\n    // end (or past 90%). pendingResume is consumed once by the\r\n    // loadedmetadata listener — quality/server switches never re-seek.\r\n    let lastProgressSave = 0;\r\n    let pendingResume = null; // seconds to seek to once metadata loads\r\n    function currentProgressMeta() {\r\n      if (!currentItem) return null;\r\n      const type = currentItem.media_type === 'tv' ? 'tv' : 'movie';\r\n      return { type, s: type === 'tv' ? selectedSeason : 0, e: type === 'tv' ? selectedEpisode : 0, title: currentItem.title || currentItem.name || '', poster: currentItem.poster_path ? `${IMG_BASE}${currentItem.poster_path}` : '', kind: type };\r\n    }\r\n    function trackProgress(force) {\r\n      const meta = currentProgressMeta();\r\n      if (!meta || !nativeActive) return;\r\n      const t = videoNative.currentTime;\r\n      const d = videoNative.duration;\r\n      if (!Number.isFinite(t) || t < 5) return;\r\n      const now = Date.now();\r\n      if (!force && now - lastProgressSave < 5000) return;\r\n      lastProgressSave = now;\r\n      if (Number.isFinite(d) && d > 0 && t >= d - 30) { markWatchedEntry(meta.type, currentItem.id, meta.s, meta.e); updateResumeButton(); return; }\r\n      saveProgressEntry(meta.type, currentItem.id, meta.s, meta.e, t, d, meta);\r\n    }\r\n    videoNative.addEventListener('timeupdate', () => trackProgress(false));\r\n    videoNative.addEventListener('pause', () => trackProgress(true));\r\n    videoNative.addEventListener('ended', () => {\r\n      const meta = currentProgressMeta();\r\n      if (meta) markWatchedEntry(meta.type, currentItem.id, meta.s, meta.e);\r\n      updateResumeButton();\r\n      armAutoNext();\r\n    });\r\n    document.addEventListener('pagehide', () => trackProgress(true));\r\n    videoNative.addEventListener('loadedmetadata', () => {\r\n      videoNative.playbackRate = currentPlaybackRate;\r\n      if (pendingResume != null && Number.isFinite(videoNative.duration) && videoNative.duration > 0) {\r\n        videoNative.currentTime = Math.min(pendingResume, Math.max(0, videoNative.duration - 10));\r\n        pendingResume = null;\r\n      }\r\n    });\r\n\r\n    // The Play button shows \"أكمل من M:SS\" when a saved position exists\r\n    // for this title/episode; the restart button appears alongside it.\r\n    function currentResumeEntry() {\r\n      if (!currentItem) return null;\r\n      const type = currentItem.media_type === 'tv' ? 'tv' : 'movie';\r\n      return getProgress(type, currentItem.id, type === 'tv' ? selectedSeason : 0, type === 'tv' ? selectedEpisode : 0);\r\n    }\r\n    function updateResumeButton() {\r\n      const label = document.getElementById('btnPlayInAppLabel');\r\n      const restart = document.getElementById('btnRestartPlay');\r\n      if (!label || !restart) return;\r\n      const entry = currentResumeEntry();\r\n      label.innerText = entry ? `أكمل من ${formatTime(entry.t)}` : 'مشاهدة فورية';\r\n      restart.classList.toggle('hidden', !entry);\r\n    }\r\n\r\n    // Auto-next episode (stage C): when a series episode ends on the\r\n    // native player, the next episode starts after a 5s countdown the\r\n    // user can cancel or skip. Embedwave cannot report \"ended\", so it\r\n    // never auto-advances.\r\n    let autoNextTimer = null;\r\n    let autoNextEpisode = null;\r\n    let currentSeasonEpisodeCount = 10;\r\n    function clearAutoNext() {\r\n      if (autoNextTimer) { clearTimeout(autoNextTimer); autoNextTimer = null; }\r\n      autoNextEpisode = null;\r\n      const bar = document.getElementById('autoNextBar');\r\n      if (bar) { bar.classList.add('hidden'); bar.classList.remove('flex'); }\r\n    }\r\n    function armAutoNext() {\r\n      clearAutoNext();\r\n      if (!currentItem || currentItem.media_type !== 'tv') return;\r\n      if (!nativeActive) return;\r\n      if (selectedEpisode >= currentSeasonEpisodeCount) return;\r\n      autoNextEpisode = selectedEpisode + 1;\r\n      let left = 5;\r\n      const bar = document.getElementById('autoNextBar');\r\n      const text = document.getElementById('autoNextText');\r\n      bar.classList.remove('hidden');\r\n      bar.classList.add('flex');\r\n      const tick = () => {\r\n        if (left <= 0) {\r\n          const nextBtn = document.querySelectorAll('.ep-btn')[autoNextEpisode - 1];\r\n          clearAutoNext();\r\n          if (nextBtn) nextBtn.click();\r\n          return;\r\n        }\r\n        text.innerText = `الحلقة التالية (حلقة ${autoNextEpisode}) خلال ${left} ثواني…`;\r\n        left--;\r\n        autoNextTimer = setTimeout(tick, 1000);\r\n      };\r\n      tick();\r\n    }\r\n\r\n    // Server + quality selection. currentServers is the servers array from\r\n    // the last /api/resolve (native server first, embedwave last).\r\n    function selectedServer() {\r\n      return currentServers ? currentServers[selectedServerIdx] : null;\r\n    }\r\n\r\n    function selectedQuality() {\r\n      const server = selectedServer();\r\n      return server ? server.qualities[selectedQualityIdx] : null;\r\n    }\r\n\r\n    function isEmbedwaveServer(server) {\r\n      return server && server.name === 'embedwave';\r\n    }\r\n\r\n    // The iframe embed server (embedwave), as opposed to a native\r\n    // direct-stream server.\r\n    function isEmbedServer(server) {\r\n      return isEmbedwaveServer(server);\r\n    }\r\n\r\n    // Sandbox flags for the embedwave iframe: scripts + same-origin so the\r\n    // player can run, but NO allow-popups / allow-top-navigation, so its\r\n    // ads cannot open tabs or hijack the page.\r\n    const EMBEDWAVE_SANDBOX = 'allow-same-origin allow-scripts allow-presentation allow-forms';\r\n\r\n    function renderServerControls() {\r\n      const wrap = document.getElementById('serverControls');\r\n      const serversRow = document.getElementById('serversRow');\r\n      const qualitiesRow = document.getElementById('qualitiesRow');\r\n      const qualityWrap = document.getElementById('qualityWrap');\r\n      if (!currentServers || currentServers.length === 0) {\r\n        wrap.classList.add('hidden');\r\n        return;\r\n      }\r\n      wrap.classList.remove('hidden');\r\n      serversRow.innerHTML = '';\r\n      currentServers.forEach((server, idx) => {\r\n        const b = document.createElement('button');\r\n        b.type = 'button';\r\n        b.className = 'min-h-[44px] px-3.5 py-1.5 rounded-md text-xs font-bold border transition ' + (idx === selectedServerIdx\r\n          ? 'bg-[#e50914] border-[#e50914] text-white'\r\n          : 'bg-[#232323] border-[#737373] text-neutral-200 hover:border-white');\r\n        b.textContent = server.name;\r\n        b.addEventListener('click', () => {\r\n          captureCurrentPlaybackTime();\r\n          selectedServerIdx = idx;\r\n          selectedQualityIdx = 0;\r\n          renderServerControls();\r\n          playSelected();\r\n        });\r\n        serversRow.appendChild(b);\r\n      });\r\n      const server = selectedServer();\r\n      qualitiesRow.innerHTML = '';\r\n      if (server && server.qualities.length > 1) {\r\n        qualityWrap.classList.remove('hidden');\r\n        server.qualities.forEach((q, idx) => {\r\n          const b = document.createElement('button');\r\n          b.type = 'button';\r\n          b.className = 'min-h-[44px] px-3.5 py-1.5 rounded-md text-xs font-bold border transition ' + (idx === selectedQualityIdx\r\n            ? 'bg-emerald-600 border-emerald-600 text-white'\r\n            : 'bg-[#232323] border-[#737373] text-neutral-200 hover:border-white');\r\n          b.textContent = q.quality;\r\n          b.addEventListener('click', () => {\r\n            captureCurrentPlaybackTime();\r\n            selectedQualityIdx = idx;\r\n            renderServerControls();\r\n            playSelected();\r\n          });\r\n          qualitiesRow.appendChild(b);\r\n        });\r\n      } else {\r\n        qualityWrap.classList.add('hidden');\r\n      }\r\n    }\r\n\r\n    // Play the currently selected server + quality.\r\n    function playSelected() {\r\n      clearAutoNext();\r\n      const server = selectedServer();\r\n      const quality = selectedQuality();\r\n      if (!server || !quality) { loadEmbedFallback(); return; }\r\n      hideModalBackdrop();\r\n      playerContainer.classList.remove('hidden');\r\n      if (isEmbedServer(server)) {\r\n        resetPlayer();\r\n        // embedwave always plays sandboxed (ads blocked): scripts +\r\n        // same-origin so the player can run, but no popups or\r\n        // top-navigation.\r\n        videoIframe.setAttribute('sandbox', EMBEDWAVE_SANDBOX);\r\n        showIframeSpinner();\r\n        videoIframe.src = quality.stream;\r\n        playerContainer.classList.remove('hidden');\r\n        updatePlayerToolbarVisibility(true);\r\n        return;\r\n      }\r\n      hideIframeSpinner();\r\n      videoIframe.src = '';\r\n      videoIframe.classList.add('hidden');\r\n      nativeActive = true;\r\n      if (quality.direct && !quality._directFailed) {\r\n        usingDirectCdn = true;\r\n        videoNative.src = quality.direct;\r\n      } else {\r\n        usingDirectCdn = false;\r\n        videoNative.src = quality.stream;\r\n      }\r\n      videoNative.playbackRate = currentPlaybackRate;\r\n      videoNative.classList.remove('hidden');\r\n      hidePlayerStatus();\r\n      updatePlayerToolbarVisibility(false);\r\n      armNativePlayTimeout();\r\n      videoNative.play().catch(() => {});\r\n    }\r\n\r\n    // Native player failure: try the next quality of the same server\r\n    // first; only when no quality is left, fall back to the sandboxed\r\n    // embedwave server.\r\n    function tryNextQualityOrFallback() {\r\n      const server = selectedServer();\r\n      if (server && !isEmbedServer(server) && selectedQualityIdx < server.qualities.length - 1) {\r\n        captureCurrentPlaybackTime();\r\n        selectedQualityIdx++;\r\n        renderServerControls();\r\n        playSelected();\r\n        showToast('الجودة السابقة مش شغالة — جارٍ تجربة جودة أخرى…');\r\n        return;\r\n      }\r\n      loadEmbedFallback();\r\n    }\r\n\r\n    // Embed fallback: pick the embedwave server if it exists and is not\r\n    // already selected (sandboxed, ads blocked). When there is no embed\r\n    // server at all, say so — never open an unsandboxed player, so no\r\n    // popup can appear. Also forgets a dead native resolve result for\r\n    // this key so the download button re-resolves instead of reusing\r\n    // the dead link.\r\n    function loadEmbedFallback() {\r\n      if (!currentItem) return;\r\n      hideModalBackdrop();\r\n      playerContainer.classList.remove('hidden');\r\n      const type = currentItem.media_type === 'tv' ? 'tv' : 'movie';\r\n      const s = type === 'tv' ? selectedSeason : undefined;\r\n      const e = type === 'tv' ? selectedEpisode : undefined;\r\n      const key = resolveKey(type, currentItem.id, s, e);\r\n      if (lastResolved && lastResolved.key === key && lastResolved.data && lastResolved.data.ok) {\r\n        lastResolved = null;\r\n      }\r\n      if (!currentServers) {\r\n        showPlayerStatus('⚠️ لا يوجد مصدر شغّال لهذا العمل حالياً.');\r\n        return;\r\n      }\r\n      const embedwaveIdx = currentServers.findIndex((s) => s.name === 'embedwave');\r\n      if (embedwaveIdx >= 0 && embedwaveIdx !== selectedServerIdx) {\r\n        selectedServerIdx = embedwaveIdx;\r\n        selectedQualityIdx = 0;\r\n        renderServerControls();\r\n        playSelected();\r\n        return;\r\n      }\r\n      showPlayerStatus('⚠️ لا يوجد مصدر شغّال لهذا العمل حالياً.');\r\n    }\r\n\r\n    function showToast(msg) {\r\n      let toast = document.getElementById('toast');\r\n      if (!toast) {\r\n        toast = document.createElement('div');\r\n        toast.id = 'toast';\r\n        toast.className = 'fixed bottom-6 left-1/2 -translate-x-1/2 z-[60] bg-slate-900 text-white text-xs font-bold px-4 py-3 rounded-2xl border border-brand-border shadow-2xl max-w-[90vw] text-center';\r\n        document.body.appendChild(toast);\r\n      }\r\n      toast.innerText = msg;\r\n      toast.classList.remove('hidden');\r\n      clearTimeout(showToast._t);\r\n      showToast._t = setTimeout(() => toast.classList.add('hidden'), 4000);\r\n    }\r\n\r\n    // Count one view per title/episode when playback starts (fire-and-\r\n    // forget; the same key is never counted twice in this session).\r\n    let lastViewKey = null;\r\n    function recordViewOnce(type, id, s, e) {\r\n      const key = resolveKey(type, id, s, e);\r\n      if (lastViewKey === key) return;\r\n      lastViewKey = key;\r\n      fetch(`${API_BASE}/api/view`, {\r\n        method: 'POST',\r\n        headers: { 'Content-Type': 'application/json' },\r\n        body: JSON.stringify({ type, id }),\r\n      }).catch(() => {});\r\n    }\r\n\r\n    // In-App Instant Player: ad-free native <video> first, then the\r\n    // sandboxed embedwave embed. No unsandboxed fallback exists anymore,\r\n    // so no popup can open from the player. The Play button resumes from\r\n    // the saved position when one exists; the restart button plays from\r\n    // the beginning.\r\n    btnPlayInApp.addEventListener('click', () => {\r\n      const entry = currentResumeEntry();\r\n      pendingResume = entry ? entry.t : null;\r\n      playActiveStream();\r\n    });\r\n    document.getElementById('btnRestartPlay').addEventListener('click', () => {\r\n      pendingResume = null;\r\n      playActiveStream();\r\n    });\r\n    document.getElementById('btnAutoNextNow').addEventListener('click', () => {\r\n      const nextBtn = autoNextEpisode ? document.querySelectorAll('.ep-btn')[autoNextEpisode - 1] : null;\r\n      clearAutoNext();\r\n      if (nextBtn) nextBtn.click();\r\n    });\r\n    document.getElementById('btnAutoNextCancel').addEventListener('click', clearAutoNext);\r\n    // Report a problem (stage F): no backend — the report text is\r\n    // prefilled (title, episode, server, quality, problem) and sent\r\n    // through Telegram's share sheet to @filmatibot.\r\n    function buildReportText(problem) {\r\n      const title = currentItem ? (currentItem.title || currentItem.name || '—') : '—';\r\n      const date = currentItem ? (currentItem.release_date || currentItem.first_air_date || '') : '';\r\n      const year = date ? date.slice(0, 4) : '';\r\n      const kind = currentItem ? (currentItem.media_type === 'tv' ? 'مسلسل' : 'فيلم') : '—';\r\n      const type = currentItem ? (currentItem.media_type === 'tv' ? 'tv' : 'movie') : 'movie';\r\n      const s = type === 'tv' ? selectedSeason : 0;\r\n      const e = type === 'tv' ? selectedEpisode : 0;\r\n      const server = selectedServer();\r\n      const quality = selectedQuality();\r\n      const lines = [\r\n        '⚠️ بلاغ مشكلة — فيلماتي',\r\n        `العمل: ${title} (${kind}${year ? ' ' + year : ''})`,\r\n      ];\r\n      if (type === 'tv') lines.push(`الموسم ${s} — الحلقة ${e}`);\r\n      lines.push(`السيرفر: ${server ? server.name : '—'} — الجودة: ${quality ? quality.quality : '—'}`);\r\n      lines.push(`المشكلة: ${problem}`);\r\n      return lines.join('\\n');\r\n    }\r\n    function shareReport(problem) {\r\n      const text = buildReportText(problem);\r\n      const shareTarget = buildShareUrl(currentItem, selectedSeason, selectedEpisode);\r\n      const url = 'https://t.me/share/url?url=' + encodeURIComponent(shareTarget) + '&text=' + encodeURIComponent(text);\r\n      window.open(url, '_blank');\r\n    }\r\n\r\n    document.getElementById('btnTrailer').addEventListener('click', () => {\r\n      if (!trailerKey) return;\r\n      resetPlayer();\r\n      hideModalBackdrop();\r\n      playerContainer.classList.remove('hidden');\r\n      videoIframe.removeAttribute('sandbox');\r\n      videoIframe.classList.remove('hidden');\r\n      showIframeSpinner();\r\n      videoIframe.src = `https://www.youtube.com/embed/${trailerKey}?autoplay=1&rel=0`;\r\n      hidePlayerStatus();\r\n      updatePlayerToolbarVisibility(true);\r\n    });\r\n\r\n    // Cinema toolbar controls: speed, PiP, theater, fullscreen, seek buttons, shortcuts, double-tap.\r\n    document.getElementById('btnSeekBack').addEventListener('click', () => seekNativeBy(-10));\r\n    document.getElementById('btnSeekFwd').addEventListener('click', () => seekNativeBy(10));\r\n    document.getElementById('playerSpeedSelect').addEventListener('change', (e) => {\r\n      currentPlaybackRate = parseFloat(e.target.value) || 1;\r\n      videoNative.playbackRate = currentPlaybackRate;\r\n    });\r\n    document.getElementById('btnPip').addEventListener('click', async () => {\r\n      try {\r\n        if (document.pictureInPictureElement) {\r\n          await document.exitPictureInPicture();\r\n        } else if (document.pictureInPictureEnabled && videoNative.requestPictureInPicture) {\r\n          await videoNative.requestPictureInPicture();\r\n        } else {\r\n          showToast('المتصفح لا يدعم صورة داخل صورة');\r\n        }\r\n      } catch (e) {\r\n        showToast('شغّل الفيديو أولاً لتفعيل صورة داخل صورة');\r\n      }\r\n    });\r\n    document.getElementById('btnTheater').addEventListener('click', (e) => {\r\n      const card = document.getElementById('modalCard');\r\n      if (!card) return;\r\n      const active = card.classList.toggle('theater-mode');\r\n      e.currentTarget.setAttribute('aria-pressed', active ? 'true' : 'false');\r\n    });\r\n    function toggleModalFullscreen() {\r\n      const target = playerContainer;\r\n      if (document.fullscreenElement) {\r\n        document.exitFullscreen().catch(() => {});\r\n        return;\r\n      }\r\n      if (target.requestFullscreen) {\r\n        target.requestFullscreen().then(() => {\r\n          if (screen.orientation && screen.orientation.lock) {\r\n            screen.orientation.lock('landscape').catch(() => {});\r\n          }\r\n        }).catch(() => {});\r\n      } else if (videoNative.webkitEnterFullscreen) {\r\n        videoNative.webkitEnterFullscreen();\r\n      }\r\n    }\r\n    document.getElementById('btnFullscreen').addEventListener('click', toggleModalFullscreen);\r\n    document.addEventListener('fullscreenchange', () => {\r\n      if (!document.fullscreenElement && screen.orientation && screen.orientation.unlock) {\r\n        try { screen.orientation.unlock(); } catch (e) {}\r\n      }\r\n    });\r\n\r\n    // Double-tap seek on mobile touchscreens without blocking native controls.\r\n    let lastTapTime = 0;\r\n    let lastTapSide = null;\r\n    videoNative.addEventListener('touchend', (e) => {\r\n      if (!nativeActive || !e.changedTouches || !e.changedTouches.length) return;\r\n      const touch = e.changedTouches[0];\r\n      const rect = videoNative.getBoundingClientRect();\r\n      if (!rect.width) return;\r\n      // Ignore taps on the bottom 48px native control bar.\r\n      if (touch.clientY > rect.bottom - 48) return;\r\n      const relX = (touch.clientX - rect.left) / rect.width;\r\n      const side = relX < 0.35 ? 'left' : relX > 0.65 ? 'right' : null;\r\n      if (!side) return;\r\n      const now = Date.now();\r\n      if (lastTapSide === side && now - lastTapTime < 280) {\r\n        seekNativeBy(side === 'left' ? -10 : 10);\r\n        lastTapTime = 0;\r\n        lastTapSide = null;\r\n      } else {\r\n        lastTapTime = now;\r\n        lastTapSide = side;\r\n      }\r\n    }, { passive: true });\r\n\r\n    // Keyboard shortcuts when the player modal is open.\r\n    document.addEventListener('keydown', (e) => {\r\n      if (mediaModal.classList.contains('hidden')) return;\r\n      const active = document.activeElement;\r\n      const typing = active && (active.tagName === 'INPUT' || active.tagName === 'TEXTAREA' || active.tagName === 'SELECT');\r\n      if (typing) return;\r\n      if (e.key === 'Escape') {\r\n        closeModal.click();\r\n        return;\r\n      }\r\n      if (!nativeActive || videoNative.classList.contains('hidden')) return;\r\n      if (e.key === 'ArrowLeft' || e.key === 'j' || e.key === 'J') {\r\n        e.preventDefault();\r\n        seekNativeBy(-10);\r\n      } else if (e.key === 'ArrowRight' || e.key === 'l' || e.key === 'L') {\r\n        e.preventDefault();\r\n        seekNativeBy(10);\r\n      } else if (e.key === 'k' || e.key === 'K' || (e.key === ' ' && (!active || active.tagName !== 'BUTTON'))) {\r\n        e.preventDefault();\r\n        if (videoNative.paused) { videoNative.play().catch(() => {}); } else { videoNative.pause(); }\r\n      } else if (e.key === 'f' || e.key === 'F') {\r\n        e.preventDefault();\r\n        toggleModalFullscreen();\r\n      } else if (e.key === 'm' || e.key === 'M') {\r\n        e.preventDefault();\r\n        videoNative.muted = !videoNative.muted;\r\n      }\r\n    });\r\n    document.getElementById('btnReport').addEventListener('click', () => {\r\n      document.getElementById('reportPicker').classList.toggle('hidden');\r\n    });\r\n    document.querySelectorAll('.report-problem-btn').forEach((btn) => {\r\n      btn.addEventListener('click', () => {\r\n        document.getElementById('reportPicker').classList.add('hidden');\r\n        shareReport(btn.dataset.problem);\r\n      });\r\n    });\r\n    document.getElementById('btnMyList').addEventListener('click', () => {\r\n      if (!currentItem) return;\r\n      const type = currentItem.media_type === 'tv' ? 'tv' : 'movie';\r\n      const meta = { title: currentItem.title || currentItem.name || '', poster: currentItem.poster_path ? `${IMG_BASE}${currentItem.poster_path}` : '', kind: type };\r\n      const added = toggleMyList(type, currentItem.id, meta);\r\n      updateMyListButton();\r\n      showToast(added ? 'تمت الإضافة لقائمتي ❤️' : 'تمت الإزالة من قائمتي');\r\n    });\r\n\r\n    async function playActiveStream() {\r\n      if (!currentItem) return;\r\n      const type = currentItem.media_type === 'tv' ? 'tv' : 'movie';\r\n      const s = type === 'tv' ? selectedSeason : undefined;\r\n      const e = type === 'tv' ? selectedEpisode : undefined;\r\n      const key = resolveKey(type, currentItem.id, s, e);\r\n      recordViewOnce(type, currentItem.id, s, e);\r\n      hideModalBackdrop();\r\n      playerContainer.classList.remove('hidden');\r\n      showPlayerStatus('⏳ جاري تجهيز مشغّل بدون إعلانات...');\r\n      const resolved = await fetchResolve(type, currentItem.id, s, e);\r\n      selectedServerIdx = 0;\r\n      selectedQualityIdx = 0;\r\n      currentServers = resolved && resolved.servers ? resolved.servers : null;\r\n      document.getElementById('downloadPicker').classList.add('hidden');\r\n      document.getElementById('botCodePanel').classList.add('hidden');\r\n      renderServerControls();\r\n      if (resolved && Array.isArray(resolved.servers)) {\r\n        lastResolved = { key, data: resolved };\r\n        syncDownloadButtonState(resolved);\r\n      }\r\n      if (resolved && resolved.ok) {\r\n        playSelected();\r\n        return;\r\n      }\r\n      // No direct source: fall back to the sandboxed embedwave server.\r\n      loadEmbedFallback();\r\n    }\r\n\r\n    // Direct Download & Telegram Bot Request\r\n    btnDirectDownload.addEventListener('click', async () => {\r\n      if (!currentItem) return;\r\n      const type = currentItem.media_type === 'tv' ? 'tv' : 'movie';\r\n      const s = type === 'tv' ? selectedSeason : undefined;\r\n      const e = type === 'tv' ? selectedEpisode : undefined;\r\n      const key = resolveKey(type, currentItem.id, s, e);\r\n      const picker = document.getElementById('downloadPicker');\r\n      const pickerRow = document.getElementById('downloadQualitiesRow');\r\n      const labelEl = document.getElementById('btnDirectDownloadLabel');\r\n      const iconEl = document.getElementById('btnDirectDownloadIcon');\r\n      const prevLabel = labelEl ? labelEl.innerText : '';\r\n      const prevIcon = iconEl ? iconEl.innerText : '';\r\n      btnDirectDownload.disabled = true;\r\n      if (iconEl) iconEl.innerText = '⏳';\r\n      if (labelEl) labelEl.innerText = 'جاري تجهيز الرابط...';\r\n      try {\r\n        let resolved = (lastResolved && lastResolved.key === key) ? lastResolved.data : null;\r\n        if (!resolved) {\r\n          resolved = await fetchResolve(type, currentItem.id, s, e);\r\n          if (resolved && Array.isArray(resolved.servers)) {\r\n            lastResolved = { key, data: resolved };\r\n          }\r\n        }\r\n        syncDownloadButtonState(resolved);\r\n        const qualities = getDownloadQualities(resolved);\r\n        if (qualities.length > 1) {\r\n          // More than one quality: show the picker; tapping one downloads it.\r\n          pickerRow.innerHTML = '';\r\n          qualities.forEach((q) => {\r\n            const b = document.createElement('button');\r\n            b.type = 'button';\r\n            b.className = 'min-h-[44px] px-3 py-1.5 rounded-md text-xs font-bold border bg-[#232323] border-[#737373] text-neutral-200 hover:border-white transition';\r\n            b.textContent = q.quality;\r\n            b.addEventListener('click', () => {\r\n              picker.classList.add('hidden');\r\n              downloadQuality(q, key);\r\n            });\r\n            pickerRow.appendChild(b);\r\n          });\r\n          picker.classList.remove('hidden');\r\n          return;\r\n        }\r\n        if (qualities.length === 1) {\r\n          await downloadQuality(qualities[0], key);\r\n          return;\r\n        }\r\n        showToast('هذا العمل متاح للمشاهدة الأونلاين فقط ولا يتوفر له ملف MP4 مباشر حالياً');\r\n      } finally {\r\n        btnDirectDownload.disabled = false;\r\n        if (!lastResolved || lastResolved.key !== key) {\r\n          if (iconEl) iconEl.innerText = prevIcon || '⬇';\r\n          if (labelEl) labelEl.innerText = prevLabel || 'تحميل مباشر (.mp4)';\r\n        } else {\r\n          syncDownloadButtonState(lastResolved.data);\r\n        }\r\n      }\r\n    });\r\n\r\n    function startAnchorDownload(q, filename) {\r\n      const a = document.createElement('a');\r\n      a.href = q.download;\r\n      a.download = filename || '';\r\n      a.rel = 'noopener';\r\n      document.body.appendChild(a);\r\n      a.click();\r\n      a.remove();\r\n    }\r\n    async function downloadQuality(q, key) {\r\n      if (!q.download) {\r\n        if (lastResolved && lastResolved.key === key && lastResolved.data && lastResolved.data.ok) {\r\n          lastResolved = null;\r\n        }\r\n        showToast('تعذر بدء التحميل المباشر لهذا العمل حالياً');\r\n        return;\r\n      }\r\n      startAnchorDownload(q, downloadFileName(selectedEpisode));\r\n      showToast('بدأ التحميل - هتلاقي الملف في التنزيلات');\r\n    }\r\n\r\n    // File name the browser saves: movies \"Title.mp4\", episodes\r\n    // \"Title S01E01.mp4\" — every episode gets its own name, so a season\r\n    // download never overwrites itself. (The anchor's download attribute\r\n    // alone can't do this cross-origin — the Worker sets the same name in\r\n    // its Content-Disposition — but it applies when the page is served\r\n    // from the Worker itself.)\r\n    function downloadFileName(ep) {\r\n      const title = (currentItem.title || currentItem.name || 'filmaty').replace(/[/\\\\:*?\"<>|]/g, '-');\r\n      if (currentItem.media_type === 'tv' && ep) {\r\n        return `${title} S${String(selectedSeason).padStart(2, '0')}E${String(ep).padStart(2, '0')}.mp4`;\r\n      }\r\n      return `${title}.mp4`;\r\n    }\r\n\r\n    // Whole-season download (stage G): resolves every episode of the\r\n    // selected season and starts one browser download after another\r\n    // (1.5s apart). Browsers may ask once to allow multiple downloads;\r\n    // an episode with no direct copy is skipped and listed.\r\n    let seasonDownloadRunning = false;\r\n    function seasonFileName(ep) { return downloadFileName(ep); }\r\n    async function downloadSeason(qualityLabel) {\r\n      if (seasonDownloadRunning || !currentItem || currentItem.media_type !== 'tv') return;\r\n      seasonDownloadRunning = true;\r\n      const list = document.getElementById('seasonDownloadList');\r\n      const wrap = document.getElementById('seasonDownloadProgress');\r\n      list.innerHTML = '';\r\n      wrap.classList.remove('hidden');\r\n      const count = currentSeasonEpisodeCount;\r\n      let started = 0;\r\n      let skipped = 0;\r\n      for (let ep = 1; ep <= count; ep++) {\r\n        const li = document.createElement('div');\r\n        li.className = 'text-[11px] font-bold text-slate-300';\r\n        li.innerText = `حلقة ${ep}… ⏳`;\r\n        list.appendChild(li);\r\n        try {\r\n          const resolved = await fetchResolve('tv', currentItem.id, selectedSeason, ep);\r\n          const qualities = resolved && resolved.ok && resolved.servers && resolved.servers[0]\r\n            ? resolved.servers[0].qualities.filter((x) => x.download)\r\n            : [];\r\n          const q = qualities.find((x) => x.quality === qualityLabel) || qualities[0];\r\n          if (!q || !q.download) { li.innerText = `حلقة ${ep} — ⚠️ مش متاحة للتحميل`; skipped++; continue; }\r\n          startAnchorDownload(q, seasonFileName(ep));\r\n          li.innerText = `حلقة ${ep} — ✅ بدأ التحميل (${q.quality})`;\r\n          started++;\r\n        } catch (e) {\r\n          li.innerText = `حلقة ${ep} — ⚠️ تعذر التحميل`;\r\n          skipped++;\r\n        }\r\n        if (ep < count) await new Promise((r) => setTimeout(r, 1500));\r\n      }\r\n      showToast(`تحميل الموسم: بدأ ${started} حلقة${skipped ? ` — ${skipped} مش متاحة` : ''}`);\r\n      seasonDownloadRunning = false;\r\n    }\r\n    document.getElementById('btnDownloadSeason').addEventListener('click', async () => {\r\n      if (!currentItem || currentItem.media_type !== 'tv') return;\r\n      const picker = document.getElementById('seasonDownloadPicker');\r\n      const row = document.getElementById('seasonDownloadQualitiesRow');\r\n      const key = resolveKey('tv', currentItem.id, selectedSeason, selectedEpisode);\r\n      let resolved = (lastResolved && lastResolved.key === key) ? lastResolved.data : null;\r\n      if (!resolved) {\r\n        resolved = await fetchResolve('tv', currentItem.id, selectedSeason, selectedEpisode);\r\n        if (resolved && Array.isArray(resolved.servers)) lastResolved = { key, data: resolved };\r\n      }\r\n      syncDownloadButtonState(resolved);\r\n      const qualities = getDownloadQualities(resolved);\r\n      if (!qualities.length) {\r\n        showToast('هذا العمل متاح للمشاهدة الأونلاين فقط ولا يتوفر له ملفات MP4 مباشرة حالياً');\r\n        return;\r\n      }\r\n      row.innerHTML = '';\r\n      qualities.forEach((q) => {\r\n        const b = document.createElement('button');\r\n        b.type = 'button';\r\n        b.className = 'min-h-[44px] px-3 py-1.5 rounded-md text-xs font-bold border bg-[#232323] border-[#737373] text-neutral-200 hover:border-white transition';\r\n        b.textContent = q.quality;\r\n        b.addEventListener('click', () => {\r\n          picker.classList.add('hidden');\r\n          downloadSeason(q.quality);\r\n        });\r\n        row.appendChild(b);\r\n      });\r\n      picker.classList.remove('hidden');\r\n    });\r\n\r\n    // Short deep-link payload: m<tmdbId> for movies, t<tmdbId>[s..e..] for series.\r\n    // (Telegram start parameters only allow A-Za-z0-9_-, max 64 chars.)\r\n    function botPayload(item, s, e) {\r\n      if (item.media_type === 'tv') return (s && e) ? `t${item.id}s${s}e${e}` : `t${item.id}`;\r\n      return `m${item.id}`;\r\n    }\r\n\r\n    // Bot send by code: ask quality first, then POST /api/bot-code and\r\n    // show the code big with copy + open-bot. No /start payload needed:\r\n    // the user just sends the code to @filmatibot.\r\n    async function openBotRequest() {\r\n      if (!currentItem) return;\r\n      const type = currentItem.media_type === 'tv' ? 'tv' : 'movie';\r\n      const s = type === 'tv' ? selectedSeason : undefined;\r\n      const e = type === 'tv' ? selectedEpisode : undefined;\r\n      const key = resolveKey(type, currentItem.id, s, e);\r\n      const panel = document.getElementById('botCodePanel');\r\n      const result = document.getElementById('botCodeResult');\r\n      const qWrap = document.getElementById('botCodeQualityWrap');\r\n      const qRow = document.getElementById('botCodeQualitiesRow');\r\n      result.classList.add('hidden');\r\n      qWrap.classList.remove('hidden');\r\n      panel.classList.remove('hidden');\r\n      let resolved = (lastResolved && lastResolved.key === key) ? lastResolved.data : null;\r\n      if (!resolved) {\r\n        resolved = await fetchResolve(type, currentItem.id, s, e);\r\n        if (resolved && Array.isArray(resolved.servers)) lastResolved = { key, data: resolved };\r\n      }\r\n      syncDownloadButtonState(resolved);\r\n      const qualities = getDownloadQualities(resolved);\r\n      qRow.innerHTML = '';\r\n      if (qualities.length === 0) {\r\n        const hasTgSendData = !!(window.Telegram && window.Telegram.WebApp && window.Telegram.WebApp.initData && window.Telegram.WebApp.sendData);\r\n        if (hasTgSendData) {\r\n          panel.classList.add('hidden');\r\n          openBotDeepLink();\r\n          return;\r\n        }\r\n        qRow.innerHTML = `\r\n          <div class=\"w-full space-y-2\">\r\n            <p class=\"text-xs text-neutral-300\">لا تتوفر جودة مباشرة لهذا العمل حالياً - يمكنك طلبه من البوت مباشرة:</p>\r\n            <a href=\"https://t.me/filmatibot?start=${botPayload(currentItem, s, e)}\" target=\"_blank\" rel=\"noopener\" class=\"inline-flex items-center justify-center min-h-[44px] px-4 py-2 rounded-md bg-[#e50914] hover:bg-red-700 text-white text-xs font-bold transition\">🚀 فتح البوت في التليجرام</a>\r\n          </div>\r\n        `;\r\n        return;\r\n      }\r\n      qualities.forEach((q) => {\r\n        const b = document.createElement('button');\r\n        b.type = 'button';\r\n        b.className = 'min-h-[44px] px-3 py-1.5 rounded-md text-xs font-bold border bg-[#232323] border-[#737373] text-neutral-200 hover:border-white transition';\r\n        b.textContent = q.quality;\r\n        b.addEventListener('click', () => requestBotCode(type, currentItem.id, s, e, q.quality));\r\n        qRow.appendChild(b);\r\n      });\r\n    }\r\n\r\n    // POST /api/bot-code, then show the code big with copy + open-bot.\r\n    async function requestBotCode(type, id, s, e, quality) {\r\n      const result = document.getElementById('botCodeResult');\r\n      const codeEl = document.getElementById('botCodeValue');\r\n      codeEl.textContent = '…';\r\n      result.classList.remove('hidden');\r\n      try {\r\n        const res = await fetch(`${API_BASE}/api/bot-code`, {\r\n          method: 'POST',\r\n          headers: { 'Content-Type': 'application/json' },\r\n          body: JSON.stringify({ type, id, s, e, quality }),\r\n        });\r\n        const data = await res.json();\r\n        if (!data || !data.ok || !data.code) {\r\n          showToast('تعذّر إنشاء الكود — جرّب الرابط المباشر');\r\n          return;\r\n        }\r\n        codeEl.textContent = data.code;\r\n        window._lastBotCode = data.code;\r\n      } catch (err) {\r\n        showToast('تعذّر إنشاء الكود — تحقق من اتصالك');\r\n      }\r\n    }\r\n\r\n    // Old deep-link behaviour, kept as a secondary option.\r\n    function openBotDeepLink() {\r\n      if (!currentItem) return;\r\n      const type = currentItem.media_type === 'tv' ? 'tv' : 'movie';\r\n      const s = type === 'tv' ? selectedSeason : undefined;\r\n      const e = type === 'tv' ? selectedEpisode : undefined;\r\n      if (window.Telegram && window.Telegram.WebApp && window.Telegram.WebApp.initData && window.Telegram.WebApp.sendData) {\r\n        window.Telegram.WebApp.sendData(JSON.stringify({ type, id: currentItem.id, s, e }));\r\n      } else {\r\n        window.open('https://t.me/filmatibot?start=' + botPayload(currentItem, s, e), '_blank');\r\n      }\r\n    }\r\n\r\n    document.getElementById('btnCopyBotCode').addEventListener('click', async () => {\r\n      const code = window._lastBotCode;\r\n      if (!code) return;\r\n      try {\r\n        await navigator.clipboard.writeText(code);\r\n        showToast('تم نسخ الكود ✅');\r\n      } catch (err) {\r\n        showToast(code);\r\n      }\r\n    });\r\n\r\n    document.getElementById('btnOpenBotPlain').addEventListener('click', () => {\r\n      const code = window._lastBotCode;\r\n      if (window.Telegram && window.Telegram.WebApp && window.Telegram.WebApp.initData && window.Telegram.WebApp.sendData && code) {\r\n        // Inside the Telegram WebApp: deliver the code to the bot directly.\r\n        window.Telegram.WebApp.sendData(JSON.stringify({ code }));\r\n      } else {\r\n        window.open('https://t.me/filmatibot', '_blank');\r\n      }\r\n    });\r\n\r\n    document.getElementById('btnBotDeepLink').addEventListener('click', openBotDeepLink);\r\n\r\n    document.getElementById('btnShareMedia').addEventListener('click', shareCurrentMedia);\r\n    btnOpenInBot.addEventListener('click', openBotRequest);\r\n\r\n    mediaModal.addEventListener('click', (e) => {\r\n      if (e.target === mediaModal) closeModal.click();\r\n    });\r\n\r\n    closeModal.addEventListener('click', () => {\r\n      if (document.fullscreenElement) document.exitFullscreen().catch(() => {});\r\n      mediaModal.classList.add('hidden');\r\n      document.body.classList.remove('overflow-hidden');\r\n      hideModalBackdrop();\r\n      resetPlayer();\r\n      playerContainer.classList.add('hidden');\r\n      updatePlayerToolbarVisibility(false);\r\n      document.getElementById('serverControls').classList.add('hidden');\r\n      document.getElementById('downloadPicker').classList.add('hidden');\r\n      document.getElementById('seasonDownloadPicker').classList.add('hidden');\r\n      document.getElementById('seasonDownloadProgress').classList.add('hidden');\r\n      document.getElementById('botCodePanel').classList.add('hidden');\r\n      document.getElementById('reportPicker').classList.add('hidden');\r\n      syncUrlWithModal('clear');\r\n      // Refresh the home sections so the continue-watching row reflects\r\n      // what was just watched.\r\n      if (homeData) renderHomeSections();\r\n    });\r\n\r\n    async function applyUrlParams() {\r\n      const params = new URLSearchParams(window.location.search);\r\n      const movieParam = Number(params.get('movie'));\r\n      const tvParam = Number(params.get('tv'));\r\n      const typeParam = params.get('type');\r\n      const idParam = Number(params.get('id'));\r\n      const sParam = Number(params.get('s')) || 1;\r\n      const eParam = Number(params.get('e')) || 1;\r\n\r\n      suppressHistorySync = true;\r\n      try {\r\n        if (Number.isInteger(movieParam) && movieParam > 0) {\r\n          await openDetails(movieParam, 'movie');\r\n        } else if (Number.isInteger(tvParam) && tvParam > 0) {\r\n          await openDetails(tvParam, 'tv', sParam, eParam);\r\n        } else if ((typeParam === 'movie' || typeParam === 'tv') && Number.isInteger(idParam) && idParam > 0) {\r\n          await openDetails(idParam, typeParam, typeParam === 'tv' ? sParam : null, typeParam === 'tv' ? eParam : null);\r\n        } else if (!mediaModal.classList.contains('hidden')) {\r\n          closeModal.click();\r\n        }\r\n      } finally {\r\n        suppressHistorySync = false;\r\n      }\r\n    }\r\n\r\n    window.addEventListener('popstate', applyUrlParams);\r\n\r\n    // Start\r\n    loadHome();\r\n    applyUrlParams();\r\n  </script>\r\n</body>\r\n</html>\r\n";
